window.__Q=window.__Q||{};window.__Q["prev/2/A2"]=[{"q":"患儿，女，3岁。咳嗽、低热1周。今出现抓耳朵，喊耳朵疼，并发现有分泌物自外耳道流出，怀疑中耳炎并发鼓膜穿孔。幼儿容易患中耳炎的原因是","o":["幼儿抵抗力低","幼儿咽鼓管短而平，管径大","幼儿咽鼓管主要为软骨部构成","幼儿咽鼓管主要由骨部构成","幼儿咽鼓管始终处于开放状态"],"a":1,"e":"幼儿咽鼓管短、平、管径大，鼻咽部分泌物易流入鼓室，是其易患中耳炎的解剖学基础，成人则少见。"},{"q":"患儿，男，7岁。跌倒时肘关节过伸造成伸直型髁上骨折。肱骨髁上骨折的部位是","o":["肱骨外上髁处","肱骨内上髁处","肱骨下端和体交界处","肱骨上端和体交界处","肱骨体"],"a":2,"e":"肱骨髁上即肱骨下端与肱骨体交界处，此处骨质薄弱，是儿童肘部最常见的骨折，易伤及邻近血管神经。"},{"q":"患者，男。从高处落下后，X线显示右前臂桡骨粉碎性骨折，需手术治疗。在前臂桡侧施行手术时容易损伤到的浅静脉是","o":["头静脉","前臂正中静脉","贵要静脉","肘正中静脉","肱静脉"],"a":0,"e":"头静脉起自手背静脉网桡侧，沿前臂桡侧及肱二头肌外侧沟上行，位置表浅；前臂桡侧手术切口易将其损伤，致手和前臂桡侧浅层静脉回流受阻。"},{"q":"患者，男，63岁。因肿瘤压迫中脑被盖后出现右上、下肢意向性震颤，右上、下肢及躯干意识性本体觉和精细触觉障碍。请问该患者可能损伤了哪些结构","o":["右小脑丘脑纤维、右红核、右内侧丘系","左小脑丘脑纤维、左红核、左脊髓丘脑束","右小脑丘脑纤维、右红核、右脊髓丘脑束","左小脑丘脑纤维、左红核、左内侧丘系","左三叉神经脊束、左红核、左内侧丘系"],"a":3,"e":"小脑丘脑纤维与红核位于中脑被盖且已交叉，左侧受损出现对侧意向性震颤；同侧内侧丘系损伤致对侧本体觉障碍。"},{"q":"患者，男，72岁。诊断为前列腺癌，需手术治疗。医生在手术中必须清楚该腺体的位置与毗邻。下列关于该腺体的描述错误的是","o":["位于膀胱与尿生殖膈之间","前方为耻骨联合","后方与直肠壶腹毗邻","底与精囊，输精管壶腹相毗邻","尖与膀胱颈邻接"],"a":4,"e":"前列腺尖朝下与尿生殖膈相接，其底朝上与膀胱颈、精囊和输精管壶腹相邻，故“尖与膀胱颈邻接”的描述错误。"},{"q":"患者，男，35岁。3天前于头部外伤后出现右眼上睑下垂，伴眼球不能向上、向内运动。诊断为动眼神经麻痹。下列眼球外肌中可能受累的是","o":["上睑提肌和外直肌","上睑提肌和下斜肌","上睑提肌和上斜肌","内直肌和上斜肌","外直肌和下斜肌"],"a":1,"e":"动眼神经支配上睑提肌、上直肌、内直肌、下直肌和下斜肌，故麻痹时上睑提肌与下斜肌均受累。"},{"q":"患者，男，60岁。在胸腔手术中见到了一些黑色淋巴结，它们是","o":["气管旁淋巴结","纵隔前淋巴结","膈上淋巴结","纵隔后淋巴结","肋间淋巴结"],"a":0,"e":"吸入的炭末随淋巴引流沉积于肺门及支气管旁淋巴结，使其呈黑色，胸腔手术中可见气管旁淋巴结发黑。"},{"q":"患者，女，43岁。某日从梯子上摔下来，左脚踝局部肿胀、疼痛、青紫。X线诊断为单纯内踝撕脱骨折。内踝是位于","o":["胫骨下端内下的突起","胫骨下端外下的突起","腓骨下端内下的突起","腓骨下端外下的突起","腓骨上端的膨大"],"a":0,"e":"内踝为胫骨下端内下方的突起，可在体表扪及；外踝由腓骨下端膨大构成，位置低于内踝。"},{"q":"患者，男，18岁。在一次篮球比赛中，不慎右肩膀重重摔到了篮球架上，锁骨处疼痛难忍，医生检查结果是锁骨骨折。锁骨易发生骨折的部位是","o":["锁骨的肩峰端","锁骨内侧2/3段","锁骨胸骨端","锁骨内外侧1/3段","锁骨内侧2/3段和外侧1/3段交界处"],"a":4,"e":"锁骨内侧2/3凸向前、外侧1/3凸向后，两段交界处为应力集中点，故骨折多发生于内、外侧交界处。"},{"q":"患者，女，35岁。诊断为脊髓空洞症，患者出现上睑下垂，瞳孔缩小的表现。试分析脊髓损伤的节段","o":["C4～5","C5～6","C7～8","T1～2","T3～4"],"a":3,"e":"支配上肢的交感神经节前纤维来自脊髓T1～2节段侧角，空洞累及该节段即出现同侧上睑下垂、瞳孔缩小。"},{"q":"患者，男，44岁。手术中损伤椎动脉后出现右侧上、下肢及躯干痛、温觉障碍。请问该患者可能损伤了以下哪个结构","o":["左侧薄束","左侧锥体束","右侧薄束","右侧脊髓丘脑束","左侧脊髓丘脑束"],"a":4,"e":"脊髓丘脑束在脊髓内交叉后上行，传导对侧痛、温觉；左侧脊髓丘脑束受损出现右侧躯干及上下肢痛温觉障碍。"},{"q":"患者，中年男性。主诉腘窝部不适或行走后发胀感。检查可见腘窝有囊性肿物需手术治疗。在腘窝手术时注意勿损伤注入腘静脉的较粗的浅静脉是","o":["大隐静脉","胫后静脉","胫前静脉","小隐静脉","腓静脉"],"a":3,"e":"小隐静脉经外踝后方沿小腿后面上行，至腘窝下角穿深筋膜注入腘静脉，腘窝手术分离时易被误伤。"},{"q":"患者，男，32岁，木匠。从屋顶上摔了下来，足外侧纵弓后端承重点骨折而变平。损伤的骨是","o":["跟骨","骰骨","距骨头","内侧楔骨","足舟骨"],"a":0,"e":"外侧纵弓由跟骨、骰骨和外侧两块跖骨构成，后端承重点为跟骨；跟骨骨折使足弓塌陷变平。"},{"q":"患者，男，50岁。无明显诱因出现眩晕、恶心、呕吐以及吞咽困难等症状，经临床检查诊断为血管闭塞引起延髓背外侧综合征。出现闭塞的血管最有可能是","o":["大脑中动脉","大脑后动脉","小脑下前动脉","小脑下后动脉","迷路动脉"],"a":3,"e":"小脑下后动脉为椎动脉最大分支，供应延髓后外侧部；其闭塞引起延髓外侧综合征，出现交叉性感觉障碍、吞咽困难和共济失调。"},{"q":"患者，女，64岁。因生锈铁钉穿破伤口，引起破伤风，造成牙颌（口腔）无法张开。最可能瘫痪的肌是","o":["颞肌","咬肌","颊肌","翼内肌","翼外肌"],"a":4,"e":"四对咀嚼肌中仅翼外肌牵引下颌向前并使其下降而张口，咬肌、颞肌、翼内肌收缩均上提下颌闭口。"},{"q":"患者，男，34岁。患者自诉主要为前鼻滴涕，有时鼻分泌物随头部姿势改变而流出，痰多且臭，分泌物为黏液脓性或脓性，经医生诊断为慢性上颌窦炎。上颌窦位于上颌骨体内，开口于","o":["中鼻道","上鼻道","下鼻道","鼻前孔","鼻后孔"],"a":0,"e":"上颌窦开口于中鼻道半月裂，窦口高于窦底，引流不畅，故上颌窦炎在鼻窦炎中最为常见。"},{"q":"老年女性患者，股骨头骨折后发现左侧肘关节屈曲无力，前臂外侧皮肤感觉丧失，肱二头肌腱反射消失，可能受损伤的神经是","o":["胸长神经","肌皮神经","正中神经","胸背神经","桡神经"],"a":1,"e":"肌皮神经支配肱二头肌、肱肌和喙肱肌，并发出前臂外侧皮神经，损伤后屈肘无力、前臂外侧感觉丧失。"},{"q":"患者，男，60岁。因血尿就诊。医生为其做膀胱镜检查，下镜时需调整阴茎方位以使尿道耻骨前弯消失减轻损伤。关于男性尿道的耻骨前弯，错误的描述是","o":["是阴茎根与体之间的弯","此弯曲凹向下","此弯曲位于耻骨联合前方","由尿道膜部和尿道海绵体构成","向上提阴茎时，此弯曲消失"],"a":3,"e":"耻骨前弯位于耻骨联合前下方，由尿道海绵体部构成，向上提拉阴茎使其贴近腹壁时该弯曲即可消失。"},{"q":"患者，男，27岁，棒球选手。在比赛中，前臂被高速球击中，肘前部的深部肌被撕裂。该患者失去功能的肌是","o":["肱桡肌","肱肌和旋后肌","旋前圆肌","旋后肌和旋前方肌","肱肌和旋前圆肌"],"a":4,"e":"肱肌与旋前圆肌位于肘窝深部，分别司屈肘和旋前，撕裂后屈肘与前臂旋前功能明显减弱。"},{"q":"患者，男，43岁。因背部外伤，出现下肢二点辨别觉丧失。患者睁眼时，运动尚可，但在闭目时，出现站立不稳，走路如踩棉花。试分析患者哪个传导束受损","o":["楔小脑束","脊髓丘脑束","脊髓小脑前束","脊髓小脑后束","薄束"],"a":4,"e":"薄束位于脊髓后索内侧，传导同侧下半身（第5胸节以下）的意识性本体感觉和精细触觉，二点辨别觉即属精细触觉；受损后闭目不能判定关节位置，出现站立不稳、走路如踩棉花。"},{"q":"患者，男，78岁。左足从麻木、发凉发展至间歇性跛行加重，直至溃疡和坏死。诊断为下肢持续性血管痉挛。可能考虑切除的结构是","o":["马尾","奇神经节","腰交感干","盆内脏神经","骶交感干"],"a":2,"e":"腰交感干发出的节后纤维随血管支配下肢，切除后解除血管痉挛、改善肢端血供，用于治疗下肢缺血。"},{"q":"患者，男，30岁。因不育就诊。医生检查后告诉小王，其不育的原因在于其生殖器输送管道梗阻。男性生殖器输送管道不包括","o":["附睾","尿道","睾丸","射精管","输精管"],"a":2,"e":"男性生殖管道由附睾、输精管、射精管和尿道组成；睾丸为生殖腺，是产生精子的器官，不属于输送管道。"},{"q":"患者，男，35岁。因心动过缓入院。心率45次/min。拟行起搏器手术治疗，起搏器导联应该连接到哪个解剖构造","o":["窦房结","房室束","房室结","右束支","左束支"],"a":0,"e":"窦房结位于上腔静脉与右心房交界处界沟上1/3的心外膜深面，是心的正常起搏点，冲动由此经结间束下传。"},{"q":"患者因脑外伤入院，检查发现经检查光照右眼，左眼无对光反射；光照左眼无对光反射，右眼有对光反射，可能损伤了","o":["左视神经损伤","左动眼神经损伤","右视神经损伤","右动眼神经损伤","视交叉中央部损伤"],"a":1,"e":"左动眼神经损伤时左眼直接、间接对光反射均消失，右眼直接和间接反射均存在，因双侧视神经的传入通路完好。"},{"q":"患者，男，65岁。因排尿困难就诊。临床常见的由于增生而引起老年男性排尿困难的是","o":["睾丸","附睾","前列腺","精囊","尿道球腺"],"a":2,"e":"前列腺位于膀胱下方并环绕尿道起始部，中老年后腺部退化、结缔组织增生，中叶和侧叶肥大压迫尿道，引起尿等待、尿线细、排尿困难甚至尿潴留。"},{"q":"患者，女，40岁。受凉后出现发热、鼻塞、咳嗽，并伴有流泪现象。这是因为","o":["鼻泪管开口处黏膜充血堵塞","结膜有炎症","泪道堵塞","泪囊炎","泪腺分泌过多"],"a":0,"e":"鼻泪管开口于下鼻道外侧壁，开口处黏膜内有丰富静脉丛，感冒时黏膜充血肿胀使鼻泪管下口闭塞，泪液向鼻腔引流不畅而溢于睑裂，故出现流泪。"},{"q":"患者，男，47岁。因车祸受伤后表现为，左侧下肢足尖下垂，不能抬起足尖，不能正常行走。最容易受损的神经是","o":["胫神经","坐骨神经","腓浅神经","腓深神经","闭孔神经"],"a":3,"e":"腓深神经支配小腿前群肌，使足背屈、伸趾；该神经损伤后足不能背屈，出现足下垂及跨阈步态。"},{"q":"患者，女，45岁。临床诊断宫颈癌行宫颈癌切除术，术后出现排尿功能障碍。可能损伤了下列哪一神经","o":["闭孔神经","阴部神经","内脏大神经","内脏小神经","盆内脏神经"],"a":4,"e":"盆内脏神经的副交感纤维支配膀胱逼尿肌并抑制尿道内括约肌，宫颈癌根治术损伤该神经后逼尿肌收缩无力，出现排尿困难。"},{"q":"老年患者，有长期糖尿病史，近期出现左侧瞳孔不能转向下外，经诊断是脑小血管阻塞，引起的脑神经麻痹。该症状是什么神经麻痹","o":["左动眼神经","右动眼神经","右滑车神经","左滑车神经","左展神经"],"a":3,"e":"滑车神经支配上斜肌，该肌收缩使眼球下转、内旋并外展，麻痹后眼球不能转向下外而出现复视。"},{"q":"患者，男，30岁。婚后3年未育。夫妻俩到医院系统检查后，患者被诊断为无精子症。负责产生精子的男性生殖腺是","o":["睾丸","附睾","前列腺","精囊","尿道球腺"],"a":0,"e":"睾丸是男性生殖腺，生精小管的生精上皮产生精子，间质细胞分泌雄激素；附睾仅为精子成熟和贮存的场所，前列腺、精囊和尿道球腺的分泌液参与精液组成。"},{"q":"患儿，男，3岁。因异物吸入呼吸道出现呼吸困难。支气管镜检查发现异物滞留于右主支气管。气管异物易进入右主支气管与其以下特征无关","o":["气管与右主支气管上缘夹角大","右主支气管管径粗","右侧嵴下角小","右主支气管走行相对直","右主支气管分支早"],"a":4,"e":"右主支气管短而粗、走行陡直、嵴下角小，故异物易坠入右侧，分支的早晚与异物走向无关。"},{"q":"患者，女，45岁，中上腹饥饿性隐痛反复发作10年，伴反酸、嗳气，进食和服用抑酸剂可缓解。该患者最可能的诊断是十二指肠溃疡。十二指肠溃疡好发部位是","o":["十二指肠降部","十二指肠升部","十二指肠球部","十二指肠下曲","十二指肠水平部"],"a":2,"e":"十二指肠上部近幽门的一段壁薄腔大、黏膜光滑无环状襞，称十二指肠球，是溃疡及穿孔的好发部位。"},{"q":"患者，女。急性膀胱尿潴留，需要行导尿术。女性尿道正确的描述是","o":["约长8～10cm","女性尿道短而直","位于阴道下半的后面","尿道下端有尿道、阴道括约肌环绕，不受意识支配","尿道旁腺感染时，可导致尿路阻塞"],"a":1,"e":"女性尿道长约3～5cm，短、宽而直，紧邻阴道前壁，故易发生逆行感染，导尿也较容易。"},{"q":"患者，男，18岁。因颈根部刀刺伤就诊。经检查怀疑伤及肺。最有可能刺伤的肺部结构是","o":["肺尖","肺底","肺门","肺根","肺韧带"],"a":0,"e":"肺尖经胸廓上口突入颈根部，高出锁骨内侧1/3上方2～3cm，故颈根部刺伤易伤及肺尖。"},{"q":"患者，男，60岁。因痰多、咳嗽就诊，怀疑为下呼吸道感染。可能感染的结构是","o":["鼻腔","口腔","喉腔","气管","胸膜顶"],"a":3,"e":"下呼吸道指气管及其各级分支，鼻腔、咽、喉属上呼吸道，故痰多咳嗽提示气管及以下部位感染。"},{"q":"患者，女，52岁。下楼时，不幸滑倒膝部着地，主诉不能伸膝关节。可能受影响的肌是","o":["半腱肌","缝匠肌","股薄肌","股四头肌","股二头肌"],"a":3,"e":"股四头肌是伸膝的唯一肌，其肌腱向下延续为髌韧带止于胫骨粗隆，损伤后不能主动伸膝。"},{"q":"患者，男，55岁。主诉左上颌牙齿疼痛。牙科检查未发现他的牙齿异常。检体时发现患者左上颌有压痛，无过敏史。最可能的诊断是","o":["蝶窦炎","前筛窦炎","后筛窦炎","上颌窦炎","额窦炎"],"a":3,"e":"上颌窦底与上颌磨牙根尖间仅隔薄骨壁，牙源性感染易波及上颌窦，出现上颌牙痛和鼻窦压痛。"},{"q":"患者，男，31岁。因车祸，出现肩胛部压痛，肩关节活动受限。X线诊断为肩胛骨骨折。最常见的骨折是","o":["肩胛颈骨折","肩胛冈骨折","肩胛盂骨折","喙突骨折","肩胛体骨折"],"a":4,"e":"肩胛骨骨折多由直接暴力引起，其中体部骨折最为常见，其次为肩胛颈、肩胛冈和肩胛盂骨折。"},{"q":"患者，男，30岁。因贝内特骨折（第一掌骨基底骨折），出现拇指运动障碍。最有可能损伤的鱼际肌是","o":["拇短展肌","拇短屈肌（浅头）","拇对掌肌","拇收肌","拇短屈肌（深头）"],"a":2,"e":"第一掌骨基底骨折使拇指对掌功能受限；拇对掌肌起自屈肌支持带和大多角骨，止于第1掌骨外侧缘，由正中神经支配，司拇指对掌。"},{"q":"患者，男，30岁，高尔夫球手。腿部受伤，导致足不能内翻。最有可能瘫痪的肌是","o":["胫骨后肌","腓骨长肌","腓骨短肌","第三腓骨肌","趾长伸肌"],"a":0,"e":"胫骨后肌起自小腿骨间膜后面，止于足舟骨粗隆，由胫神经支配，主要作用是使足内翻并协助跖屈；该肌瘫痪则足不能内翻。"},{"q":"患者，男，50岁。因腮腺恶性肿瘤，手术切除面神经后，咀嚼后食物滞留于口腔前庭，可能损伤的肌是","o":["咬肌","翼内肌","颞肌","颊肌","翼外肌"],"a":3,"e":"颊肌收缩使颊部紧贴牙列，将食物推向牙间；面神经损伤后颊肌瘫痪，食物滞留于口腔前庭。"},{"q":"患者，男，42岁。2年前出现视近物模糊，视远物清楚，诊断为老视。其解剖学基础是","o":["晶状体曲度变大","晶状体曲度变小","晶状体弹性减弱","角膜曲度变大","晶状体浑浊"],"a":2,"e":"随年龄增长晶状体核增大变硬、弹性减退，睫状肌萎缩，调节能力下降，视近物时晶状体不能充分变凸，故视近模糊而视远清楚，形成老视。"},{"q":"患者，女，48岁。6个月前发现右颈前一肿物，大小约3cm×3cm。甲状腺彩超：甲状腺右叶3.2cm×3.5cm，左叶1.9cm×1.9cm，峡部厚1.0cm，甲状腺实质回声不均匀，右叶可见大小约3.9cm×3.2cm不均匀回声团，边界欠清，周边及内部可见血流信号。诊断：甲状腺癌。治疗行甲状腺切除术时需要结扎哪几条动脉","o":["甲状腺上、下动脉","颈总动脉","面动脉","颈外动脉","甲状腺中动脉"],"a":0,"e":"甲状腺由甲状腺上动脉和甲状腺下动脉供血，前者发自颈外动脉，后者发自甲状颈干，甲状腺切除术中需结扎这两条动脉。"},{"q":"患者，男，50岁。因右侧下颌第一磨牙牙龈肿痛就医。与传导该痛觉相关的结构是","o":["孤束","内侧丘系","外侧丘系","脊髓丘系","三叉丘系"],"a":4,"e":"下颌牙的痛觉经三叉神经下颌支传入，二级纤维交叉后组成三叉丘系，上行止于背侧丘脑腹后内侧核。"},{"q":"患者，男，27岁。由于胸小肌瘫痪而无法向前和向下拉伸肩胛骨。最可能的原因是","o":["锁骨骨折","臂丛后索损伤","喙突骨折","腋神经损伤","腋窝后壁缺损"],"a":2,"e":"胸小肌起自第3～5肋，止于肩胛骨喙突，收缩时拉肩胛骨向前下方；喙突骨折可撕脱其止点致该肌瘫痪。臂丛后索损伤累及的是肩胛下神经、胸背神经和腋神经。"},{"q":"患者，女，72岁。主因眩晕、努嘴、半身不自主运动1天就诊。诊断为间脑出血并发症手足徐动舞蹈样半身舞蹈症。出血位置可能位于","o":["背侧丘脑","底丘脑","上丘脑","下丘脑","后丘脑"],"a":1,"e":"底丘脑核属锥体外系，对苍白球起抑制作用；一侧底丘脑核损伤后苍白球活动过度，出现对侧半身不自主的舞蹈样、手足徐动样运动，即半身颤搐。"},{"q":"患者，女，34岁。因从高处坠落导致左侧上肢不能主动活动，手腕不能抬起，前臂后部的骨骼肌麻痹无力，手背第1、2掌骨之间的皮肤感觉消失。应当考虑最容易受损的神经是","o":["尺神经","腋神经","桡神经","肌皮神经","正中神经"],"a":2,"e":"桡神经在肱骨中段后方紧贴桡神经沟，骨折易损伤，出现垂腕、前臂伸肌群瘫痪及第1、2掌骨间皮肤感觉障碍。"},{"q":"患者，男，27岁。车祸后昏迷不醒。检查瞳孔对光反射有助于判断病情。下列参与此反射的结构是","o":["睫状神经节","翼腭神经节","耳神经节","三叉神经节","下颌下神经节"],"a":0,"e":"瞳孔对光反射的传出纤维为动眼神经的副交感节前纤维，在睫状神经节换元后支配瞳孔括约肌。"},{"q":"患者，女，30岁。外阴部被撞伤后疼痛难忍并出现肿块。最可能发生血肿的部位是","o":["阴阜","阴蒂","大阴唇","小阴唇","前庭大腺"],"a":2,"e":"大阴唇皮下富含脂肪、血管和淋巴管，外伤后易形成血肿，故外阴撞伤后的肿块多位于大阴唇。"},{"q":"患者，男，48岁。主诉复视（双物象）。医生检查发现左眼内收障碍，并左眼角膜反射缺失。损伤部位最有可能是","o":["眶下裂","视神经孔","眶上裂","圆孔","卵圆孔"],"a":2,"e":"眶上裂内有动眼、滑车、展神经及眼神经通过，损伤后内直肌麻痹致内收障碍，眼神经受损则角膜反射消失。"},{"q":"患者，男，40岁。4天前右上唇处有一疖肿，刮脸时不慎刮破，并挤压之，引起面部感染，进而引起颅内感染。以下最先被感染的部位是","o":["横窦","直窦","海绵窦","上矢状窦","下矢状窦"],"a":2,"e":"面静脉在口角以上缺乏静脉瓣，经眼上、眼下静脉与海绵窦交通，面部感染挤压后细菌可逆行入颅。"},{"q":"患者，女，30岁。主要症状是患侧前臂和手的疼痛麻木。提携重物可使麻木加重，肩臂抬举时减轻或消失。检查可见患侧肩下移，锁骨上方可触得有搏动而震颤的块状物，有压痛；颈肩活动正常；牵拉患侧上肢并将头颈向对侧推移时，患侧桡动脉搏动减弱或消失；手力量减弱；患侧眼部可见有霍纳综合征。X射线检查可见有颈肋过长。诊断为胸廓上口综合征。组成胸廓上口的结构是","o":["由胸骨角、第1对肋及第1胸椎椎体围成","由胸骨剑突、第1对肋及第1胸椎椎体围成","由胸骨柄上缘、第1对肋及第1胸椎椎体围成","由胸骨柄上缘、锁骨及第1胸椎椎体围成","由胸骨柄上缘、第1对肋及第7颈椎椎体围成"],"a":2,"e":"胸廓上口由胸骨柄上缘、第1对肋和第1胸椎椎体围成，是颈部与胸腔之间的通道，前窄后宽。"},{"q":"患者，男，20岁。感冒1周，逐渐出现耳部不适，发闷、疼痛，初步诊断为中耳炎。上呼吸道感染可以引起中耳炎，与下列哪个解剖结构有关","o":["鼓室","咽鼓管","外耳道","乳突窦","鼻咽"],"a":1,"e":"咽鼓管咽口平时闭合，吞咽时开放，上呼吸道感染时病原体经咽鼓管上行至鼓室引起中耳炎。"},{"q":"患者，男，55岁。因脑干肿瘤压迫动脉后出现左侧头面部痛温觉障碍，右上、下肢及躯干意识性本体感觉和精细触觉障碍等。请问该患者可能损伤了哪些结构","o":["左侧内侧丘系、左侧脊髓丘脑束","左侧三叉神经脊束、左侧内侧丘系","右侧三叉神经脊束、右侧脊髓丘脑束","左侧内侧丘系、右侧脊髓丘脑束","左侧三叉神经脊束、右侧内侧丘系"],"a":1,"e":"左侧三叉神经脊束受损出现同侧即左侧头面部痛温觉障碍，左侧内侧丘系受损出现对侧即右侧上、下肢及躯干意识性本体感觉和精细触觉障碍，与患者表现一致。"},{"q":"患者，女，22岁。头部受伤3小时入院。查体时发现：患者对呼唤有睁眼反应，能躲避刺痛，但叙述问题错误，眼眶青紫，球结膜下瘀斑，鼻腔有血性脑脊液流出，诊断结果为颅前窝骨折。组成颅前窝的结构不包括","o":["筛骨筛板","额骨眶部","蝶骨小翼","眶上裂","鸡冠"],"a":3,"e":"颅前窝由额骨眶部、筛骨筛板和蝶骨小翼构成，筛板中央有鸡冠；眶上裂位于蝶骨大、小翼之间，属颅中窝。"},{"q":"患者，女，56岁。有风湿性心脏病史，一直服用药物治疗，近期出现心脏衰竭入院。入院彩超检查发现三尖瓣狭窄严重，拟行手术瓣膜置换治疗。手术过程中应注意避免损失的是","o":["Bachmann束","Wenchebach束","Thorel束","His束","Koch三角"],"a":3,"e":"房室束穿右纤维三角前行于室间隔膜部后下缘，三尖瓣手术操作靠近此区，易损伤房室束而致房室传导阻滞。"},{"q":"患者，男，30岁。因急性阑尾炎行阑尾切除术，在手术时寻找阑尾最可靠的方法是","o":["在右髂窝内寻找","McBurney点的深面","在回盲部寻找","沿盲肠的结肠带向下寻找","在盲肠的末端寻找"],"a":3,"e":"盲肠和结肠的三条结肠带均会聚于阑尾根部，术中沿结肠带向下追踪是寻找阑尾最可靠的方法。"},{"q":"患者，男，45岁。主诉：阵发性全腹痛，伴恶心、呕吐8小时。现病史：患者于入院当日晨7时早饭后到田间劳动，9时左右突然感到全腹剧痛，以脐周为甚，如刀割样，恶心及呕吐，突出物为所进食的稀饭，并觉全身出冷汗，即到当地医院诊治，经注射止痛针后，症状略缓解，但半小时后又发作剧痛，呈持续性，阵发性加剧，无放射性，辗转不安，不愿平卧，呕吐频繁，自觉腹部逐渐膨胀，因而用车转送入院。起病后无发热，无大便及肛门排气，小便1次，量少而赤。体格检查发现肠型，有腹膜刺激征。X线腹部透视可见小肠扩张及有多个大小不等的、呈阶梯状的积液平段。初步诊断为肠梗阻。行开腹探查术，术中见小肠有坏死现象，行小肠切除术，需结扎肠系膜上动脉。有关肠系膜上动脉的说法，下列正确的是","o":["平第12胸椎发自腹主动脉","营养全部小肠","行于肠系膜内","分布于全部结肠","经十二指肠水平部的后方下行"],"a":2,"e":"肠系膜上动脉平第1腰椎发自腹主动脉，经十二指肠水平部前方进入肠系膜根，行于肠系膜内，供应空回肠及右半结肠。"},{"q":"患者，男，45岁。因外伤后右眼出现斜视，诊断为内直肌瘫痪。其可能出现的斜视为","o":["内上斜视","外下斜视","内斜视","外斜视","外上斜视"],"a":3,"e":"内直肌由动眼神经支配，收缩使瞳孔转向内侧；该肌瘫痪后外直肌失去拮抗，将眼球拉向外侧，故出现外斜视。"},{"q":"患者因颅内肿瘤入院，入院检查发现患者意识清楚但角膜反射消失。其颅内肿瘤可能损伤了什么神经","o":["视神经或动眼神经","视神经或三叉神经","动眼神经或三叉神经","三叉神经或面神经","动眼神经或面神经"],"a":3,"e":"角膜反射由三叉神经眼支传入、面神经颧支传出，反射弧两端任一受损均使角膜反射消失，故提示三叉神经或面神经损伤。"},{"q":"患儿，男，12岁。半年前因摔伤后出现歪头视物，视力正常，诊断为右眼上斜肌麻痹。其受累的神经为","o":["动眼神经","滑车神经","展神经","眼神经","视神经"],"a":1,"e":"上斜肌由滑车神经支配，收缩使瞳孔转向下外；该肌麻痹后眼球不能外下转动，患者常歪头视物以减轻复视。"},{"q":"患者，男，52岁，是一位搬运工。一次搬重物后，腰部疼痛，一侧下肢麻木、疼痛症状。经检查诊断为腰4～5腰椎间盘突出症。椎间盘的纤维环破裂，髓核易向","o":["后外侧脱出","后内侧脱出","前外侧脱出","前内侧脱出","向正前方脱出"],"a":0,"e":"纤维环后外侧部最薄且无后纵韧带加强，髓核多向后外侧突出压迫同侧神经根，为椎间盘突出最常见类型。"},{"q":"患儿，女，10岁。感冒后出现声音嘶哑，咽喉部疼痛、刺痒，有异物感。逐渐发展为吸气性呼吸困难。入院诊断为急性喉炎伴喉黏膜水肿。喉黏膜水肿最有可能发生的部位是","o":["喉前庭黏膜","喉中间腔黏膜","喉室黏膜","声门下腔黏膜","喉口处黏膜"],"a":3,"e":"声门下腔黏膜下组织疏松，炎症时易发生水肿，婴幼儿尤为明显，可致喉阻塞和吸气性呼吸困难。"},{"q":"患者，男，42岁。间歇性发热5天。入院查体肝区有叩痛，CT见肝右叶脏面有数个液性暗区，考虑为肝脓肿。医生嘱咐该患者应避免仰卧位，是为了避免脓液在下列哪个间隙积聚","o":["网膜囊","肝肾隐窝","右结肠旁沟","右肠系膜窦","腹膜外间隙"],"a":1,"e":"仰卧位时肝肾隐窝是腹膜腔最低处，肝脓肿破溃的脓液易积聚于此，故患者应避免仰卧以减缓脓液聚集。"},{"q":"患者，女，55岁。有风湿病史，经检查发现三尖瓣狭窄比较严重，入院后决定进行更换三尖瓣治疗。在手术治疗过程中，为了防止误伤右束支，应注意保护的解剖结构是","o":["卵圆窝","Todaro腱","Koch三角","隔缘肉柱","室间隔膜部"],"a":3,"e":"右束支自房室束发出后沿隔缘肉柱走行至右室前壁，手术中牵拉或切断该结构易伤及右束支。"},{"q":"患者，女，48岁。因肝癌需行肝左叶切除术。关于肝的分叶的描述，正确的是","o":["两个半肝，2个叶","两个半肝，3个叶","两个半肝，4个叶","两个半肝，5个叶","两个半肝，6个叶"],"a":3,"e":"肝按Glisson系统分为左、右半肝共5叶，即左外叶、左内叶、右前叶、右后叶和尾状叶。"},{"q":"患者，女，52岁。因脑干肿瘤压迫动脉后出现右侧上、下肢及躯干痛、温觉障碍，右侧上、下肢及躯干意识性本体感觉和精细触觉障碍等。请问该患者可能损伤了哪些结构","o":["左侧内侧丘系、左侧脊髓丘脑束","右侧三叉神经脊束、左侧脊髓丘脑束","右侧内侧丘系、右侧脊髓丘脑束","左侧三叉神经脊束、右侧脊髓丘脑束","左侧三叉神经脊束、右侧内侧丘系"],"a":0,"e":"内侧丘系与脊髓丘脑束在到达丘脑前均已交叉，左侧病变使右侧躯干四肢痛温觉及本体感觉、精细触觉同时障碍。"},{"q":"患者，男，67岁。因酒后不慎摔伤头部伴意识不清1小时急诊收入院。入院查体：T 36、5℃，BP 150/80mmHg，P 67次/min，R 18次/min；患者神志清楚，查体合作；双侧瞳孔等大等圆，直径2.5mm，对光反射存在；颈抵抗阴性；双肺呼吸音清；心律齐；腹软，无压痛；肝脾肋下未及，对疼痛刺激反应敏感，语言对答如流。诉右额颞部及后枕部胀痛激烈难忍，肢体活动好。CT：右侧额颞叶硬膜外血肿，后枕部血肿，约10ml，脑挫裂伤；约30分钟后患者出现呼之不应。查体：不合作，对疼痛刺激反应减弱，右侧瞳孔大于左侧，直径4mm∶2.5mm，对光反射存在，P 54次/min，R 16次/min，BP 170/70mmHg，血氧饱和度90%。关于引起血肿的脑膜中动脉的起源及入颅部位的描述，正确的是","o":["经圆孔进入颅腔","颈外动脉的直接分支","颈内动脉的分支","经卵圆孔进入颅腔","上颌动脉的分支"],"a":4,"e":"脑膜中动脉起自上颌动脉，经棘孔入颅，行于颞骨内面的动脉沟中，骨折时易撕裂形成硬膜外血肿。"},{"q":"患者因急性排尿困难伴会阴部疼痛不适就诊。医生检查后诊断为：男性尿道第2个生理性狭窄结石梗阻。该狭窄位于","o":["尿道内口","尿道膜部","尿道球部","尿道外口","舟状窝"],"a":1,"e":"男性尿道三个狭窄由近至远为尿道内口、尿道膜部和尿道外口，第二狭窄即穿尿生殖膈的膜部，结石最易在此嵌顿。"},{"q":"患者，男，38岁。发现四肢肥大10余年。检查可见手指、脚趾肥大，下颌突出，鼻子增大。医生诊断为肢端肥大症。该病为下列哪个结构异常分泌激素促进骨的生长发育所致","o":["肾上腺皮质","肾上腺髓质","垂体前叶","垂体后叶","胸腺"],"a":2,"e":"腺垂体即垂体前叶分泌生长激素，可刺激骺软骨生长使骨增长；骨骼发育成熟后该激素分泌过多即引起肢端肥大症，表现为手足肥大、下颌突出、鼻增大。"},{"q":"患者，男，49岁。因强直性脊柱炎引起脊柱变形（驼背）。引起形态改变的原因是","o":["颈椎后突","胸椎前突","胸椎后突","腰椎后突","腰椎前突"],"a":2,"e":"正常脊柱侧面观有颈、腰前凸和胸、骶后凸；胸椎后凸过度即形成驼背，强直性脊柱炎使胸段后凸加大，导致本例形态改变。"},{"q":"患者，男，19岁。感冒发热1周，耳部疼痛，发闷，听力下降。医生欲行鼓膜检查。检查该患者外耳道和鼓膜时，应将耳郭拉向","o":["后上方","前上方","后下方","前下方","后方"],"a":0,"e":"成人外耳道呈S形弯曲，检查鼓膜时须将耳郭向后上方牵拉，使外耳道变直，婴幼儿则向后下方。"},{"q":"患者，男，40岁。原因未明的胸腔积液，需作胸膜腔诊断性穿刺，作胸腔积液涂片、培养、细胞学和生化学检查以明确病因。一般常取肩胛线第7～8肋间进行，触摸到的肩胛下角平对","o":["第6肋","第7肋","第8肋","第9肋","第10肋"],"a":1,"e":"肩胛下角平对第7肋，是计数肋和选择胸膜腔穿刺肋间的标志，肩胛线第7～8肋间即位于其下方。"},{"q":"患者，女。近期感觉下腹部有坠落感及月经量大而入院就诊。B超及子宫镜确诊为子宫黏膜下肌瘤。此患者行全子宫切除术时，不需要切除哪一韧带","o":["子宫阔韧带","子宫圆韧带","子宫主韧带","子宫骶韧带","骨盆漏斗韧带"],"a":4,"e":"骨盆漏斗韧带即卵巢悬韧带，内含卵巢血管，是维持卵巢位置的结构；全子宫切除保留卵巢时不必切断。"},{"q":"患者，男，57岁。左季肋部被汽车撞伤5小时，口渴、心悸、头晕1小时入院。患者5小时前被汽车撞中左季肋部，当时疼痛剧烈，即至医院就诊。诊断为左胸肋骨骨折，卧床休息和局部固定后感觉好转，1小时前觉全腹疼痛发胀，伴头晕、心悸，口渴、烦躁。查体：体温37.0℃，脉搏110次/min，血压92/60mmHg，神清，面色苍白，心肺（-），左季肋部皮下瘀斑、压痛，腹稍胀，全腹有明显压痛，以左上腹为著，肌紧张不明显，但有明显反跳痛，移动性浊音（±），肠鸣音可闻，弱。化验：血红蛋白80g/L，白细胞90×109/L。诊断：①脾破裂，腹腔内出血；②左胸肋骨骨折。开腹探查：脾切除。问脾动脉分支分布范围不包括","o":["胃","胰","胆囊","大网膜","脾"],"a":2,"e":"脾动脉沿胰上缘左行，沿途发出胰支、胃短动脉、胃网膜左动脉和脾支；胆囊则由肝右动脉发出的胆囊动脉供血。"},{"q":"患者，男，65岁。表现为静止性震颤，临床诊断为帕金森病。与此病病理变化相关的是","o":["皮质-新纹状体-背侧丘脑-皮质环路","新纹状体-黑质环路","苍白球-底丘脑环路","皮质-脑桥-小脑-皮质环路","胆碱能通路"],"a":1,"e":"新纹状体与黑质之间存在往返纤维联系，黑质多巴胺能神经元变性使纹状体多巴胺含量降低，是帕金森病静止性震颤、肌强直等表现的病理基础。"},{"q":"患者，男，50岁。在闭眼时不能确定损伤左侧关节的位置、运动方向以及两点间距离，损伤的结构有可能是","o":["右侧薄束","右侧楔束","右侧内侧丘系","右侧脊髓胸核","小脑右半部分"],"a":2,"e":"关节位置觉、运动方向及两点辨别觉属意识性本体感觉，经薄束核、楔束核交叉后由内侧丘系传导，故左侧肢体障碍提示右侧内侧丘系损伤。"},{"q":"患者，女，50岁。脑出血后，出现典型的“三偏”症状。临床诊断为内囊病变。其破裂出血的血管可能是","o":["脉络丛前动脉","大脑前动脉","前交通动脉","迷路动脉","豆纹动脉"],"a":4,"e":"豆纹动脉自大脑中动脉起始部垂直穿前穿质，供应尾状核、豆状核及内囊后肢，行程呈S形弯曲，高血压动脉硬化时易破裂，故称出血动脉。"},{"q":"患者，女，25岁。因咳嗽、胸痛就诊。胸部平片显示胸腔积液。正常情况下，在腋中线处，胸膜腔的最低点位于","o":["第6肋","第7肋","第8肋","第10肋","第11肋"],"a":3,"e":"胸膜下界在腋中线处与第10肋相交，故直立位时胸膜腔最低点位于第10肋水平，积液常在此积聚。"},{"q":"患儿，女，5岁。近2天腰痛，两腿痛。突然发热39.5℃。次日早晨不能下床，左下肢不能活动。检查：发现头、颈、两上肢和右腿无运动障碍，左下肢完全瘫痪，左腿肌张力减退，腱反射（膝和跟腱）消失。3周后，左大腿能够屈收，并能伸膝，但其他运动未见恢复。1个月后，足肌、小腿肌及大腿后面肌松弛，明显萎缩。无其他任何感觉障碍。试分析脊髓损伤的主要节段","o":["L4～S2","L1～L4","L2～S2","L1～L3","S1～S3"],"a":0,"e":"左下肢弛缓性瘫痪伴足肌、小腿肌及大腿后面肌萎缩而无感觉障碍，提示腰骶膨大前角细胞受损，累及L4～S2节段。"},{"q":"患者，男，25岁。1年前发现左颈部圆形包块，表面光滑，可活动；1年内包块缓慢长大，时有压迫感，无其他自觉症状。入院诊断为“左迷走神经鞘瘤”。若该肿瘤持续长大，患者最可能出现以下哪种症状","o":["声音嘶哑","伸舌无力","垂肩","鼻唇沟变浅","不能闭眼"],"a":0,"e":"迷走神经在颈部发出喉返神经支配声带肌，肿瘤增大压迫该神经可致声带麻痹，出现声音嘶哑。"},{"q":"患者，女，50岁。在锁骨上三角内触到了肿大的左锁骨上淋巴结。该肿瘤细胞来源于下列哪个器官","o":["甲状腺","胸腺","胃","睾丸","气管"],"a":2,"e":"胃的淋巴引流经腹腔淋巴结、肠干入胸导管，癌细胞栓子可滞留于胸导管注入静脉角前的左锁骨上淋巴结（Virchow淋巴结），故该处肿大常提示胃癌。"},{"q":"患者，男，45岁。自诉外出时不慎迷眼，出现明显异物感，伴有畏光及流泪。下列结构中可能伤及的是","o":["结膜","虹膜","角膜","眼睑","巩膜"],"a":2,"e":"角膜上皮富含感觉神经末梢，是眼球最敏感的结构，异物刺激后出现明显异物感、畏光和流泪。"},{"q":"患者，男，30岁。车祸导致近侧腕骨损伤。最有可能损伤的骨是","o":["头状骨","钩骨","大多角骨","三角骨","小多角骨"],"a":3,"e":"近侧列腕骨由桡侧向尺侧为手舟骨、月骨、三角骨和豌豆骨，选项中仅三角骨属于近侧列。"},{"q":"患儿，男，4岁。因呼吸困难不能平卧1年入院。可能是以下哪个结构的肥大","o":["舌扁桃体","咽扁桃体","腭舌弓","咽鼓管扁桃体","腭咽弓"],"a":1,"e":"咽扁桃体位于鼻咽顶后壁，儿童期淋巴组织增生肥大可堵塞鼻后孔，出现鼻塞、张口呼吸而不能平卧。"},{"q":"患者，女，45岁。因车祸导致左侧股骨髁上骨折，表现为小腿后群肌麻痹，足不能用足尖站立，足底皮肤感觉障碍。最容易受损的神经是","o":["股神经","胫神经","腓总神经","腓浅神经","坐骨神经"],"a":1,"e":"胫神经在腘窝及小腿后区发出肌支支配小腿后群肌，并分出皮支至足底皮肤；股骨髁上骨折易伤及胫神经，致足不能跖屈、不能用足尖站立及足底感觉障碍。"},{"q":"患者，女，50岁。伸舌时舌尖偏向右侧，为下面哪块肌肉瘫痪","o":["左侧颏舌肌","左侧舌骨舌肌","右侧颏舌肌","右侧舌骨舌肌","左侧茎突舌肌"],"a":2,"e":"颏舌肌起于颏棘止于舌中线两侧，单侧瘫痪时健侧肌力占优，舌尖偏向患侧，故伸舌偏右为右侧颏舌肌瘫痪。"},{"q":"患者，女，39岁。手术中发现胸导管上段损伤。可能出现的是下述哪种情况","o":["下肢水肿","右侧乳糜胸","上肢水肿","眼睑水肿","左侧乳糜胸"],"a":4,"e":"胸导管在胸上段行于食管左后方，紧贴左侧纵隔胸膜，该段损伤后乳糜液漏入左侧胸膜腔，形成左侧乳糜胸。"},{"q":"患者，男，56岁。表现为舌下神经交叉性偏瘫的症状，临床影像学资料表明，出现血管栓塞，可能发生栓塞的动脉是","o":["豆纹动脉","椎动脉延髓支","基底动脉分支","小脑上动脉分支","大脑后动脉分支"],"a":1,"e":"延髓内侧综合征又称舌下神经交叉性偏瘫，由椎动脉的延髓支阻塞引起，累及锥体束、内侧丘系和舌下神经根。"},{"q":"患者，女，27岁。停经6周，突发左下腹痛2小时，伴有里急后重。诊断考虑输卵管妊娠伴急性破裂。此时如果B超检查会发现积液会积聚在","o":["阴道后穹隆","阴道侧穹隆","膀胱子宫陷凹","直肠子宫陷凹","阴道前穹隆"],"a":3,"e":"直肠子宫陷凹即Douglas腔，位于直肠与子宫之间，为腹膜腔最低处，与阴道后穹仅隔阴道后壁和腹膜；输卵管妊娠破裂出血多积聚于此，可经阴道后穹穿刺抽出。"},{"q":"患者，男，30岁。右下腹持续疼痛，伴发热1天。查体见全腹紧张，右下腹压痛明显，且有反跳痛，肠鸣音弱，初步诊断为腹部器官病变伴发急性腹膜炎。请问，可能发生病变的器官是","o":["膀胱","输尿管结石","阑尾","肾","直肠"],"a":2,"e":"阑尾位于右髂窝，炎症时右下腹出现固定压痛与反跳痛，是急性腹膜炎最常见的原发器官。"},{"q":"患者，男，24岁。背部被刺伤，导致脊髓侧索被切断。可造成切断部位的功能障碍包括","o":["同侧随意运动及深、浅部感觉丧失","同侧随意运动丧失及对侧痛、温度觉障碍","同侧腱反射消失，触觉和压觉丧失","同侧痛、温度觉全部丧失","对侧随意运动丧失"],"a":1,"e":"脊髓侧索含皮质脊髓侧束和脊髓丘脑侧束，切断后出现同侧痉挛性瘫痪及对侧痛、温觉障碍。"},{"q":"患者，女，49岁。因脑干肿瘤压迫动脉后出现左侧眼球外直肌麻痹，双眼左侧凝视麻痹，左侧面肌麻痹，眩晕，眼球震颤，左侧头面部痛温觉障碍等。请问该患者可能损伤了哪些结构","o":["左侧展神经、左侧面神经、左侧前庭蜗神经、左侧三叉神经脊束","右侧展神经、右侧面神经、右侧前庭蜗神经、右侧三叉神经脊束","右侧展神经、左侧面神经、左侧前庭蜗神经、左侧脊髓丘脑束","左侧展神经、左侧面神经、左侧前庭蜗神经、左侧脊髓丘脑束","右侧展神经、右侧面神经、右侧前庭蜗神经、右侧脊髓丘脑束"],"a":0,"e":"脑桥下部外侧病变累及左侧展神经、面神经、前庭蜗神经和三叉神经脊束，出现同侧外展麻痹、面瘫、眩晕及面部痛温觉障碍。"},{"q":"患者，男，70岁。轻微外力跌倒时，腕关节处于背伸及前臂旋前位、手掌着地，暴力集中于桡骨远端松质骨处而引起骨折。检查发现骨折远端向背侧及桡侧移位，可诊断为","o":["桡骨远端伸直型骨折（Colles骨折）","桡骨远端屈曲型骨折（Smith骨折）","桡骨干骨折","桡骨头骨折","桡骨颈骨折"],"a":0,"e":"桡骨远端伸直型骨折发生于腕背伸、手掌着地跌倒，远折端向背侧及桡侧移位，即Colles骨折。"},{"q":"患者，男，38岁。因头部外伤后出现左眼瞳孔不能转向内方。受累的眼外肌是","o":["外直肌","内直肌","下斜肌","上斜肌","上直肌"],"a":1,"e":"内直肌由动眼神经支配，起自总腱环，止于巩膜内侧赤道前方，收缩使瞳孔转向内侧；该肌瘫痪后眼球不能内转，出现外斜视。"},{"q":"患者，女，28岁。颅内压增高，被诊断为小脑幕切迹疝。最易压迫的神经","o":["动眼神经","展神经","滑车神经","眼神经","视神经"],"a":0,"e":"小脑幕切迹疝时海马旁回和钩经切迹下移，压迫同侧大脑脚和动眼神经，故最早出现患侧瞳孔散大、上睑下垂。"},{"q":"患者，男，35岁。因心律失常入院。经24小时动态心电图检查，诊断为室上性心动过速。这种疾病最有可能是哪个解剖结构异常造成的","o":["窦房结","房室束","房室结","右束支","左束支"],"a":2,"e":"房室结是房室交界区的主要传导结构，存在双径路及折返机制，为室上性心动过速最常见的发生基础。"},{"q":"患者，男，68岁。近期劳累后感觉胸前区和左臂内侧皮肤疼痛。根据牵涉性痛的特点，应当首先考虑下列哪一器官可能出现病变","o":["胆囊","肝","胃","左肺","心"],"a":4,"e":"心的传入纤维经交感神经至T1～5脊神经节，其皮节与左胸前区、左臂内侧重叠，故心肌缺血出现该区牵涉痛。"},{"q":"患者以过度嗜睡、猝倒、睡眠瘫痪及入眠期幻觉等症状入院，诊断为发作性嗜睡。引起该疾病的原因可能是","o":["下丘脑外侧区的网状激活系统受损","结节漏斗核受损","下丘脑腹后内侧核受损","鞍区受损","丘脑核受损"],"a":0,"e":"下丘脑外侧区含食欲素神经元，参与上行网状激活系统维持觉醒；该区受损使觉醒调节障碍，出现日间过度嗜睡、猝倒及睡眠瘫痪。"},{"q":"患儿，男，16岁。查体：环指掌指关节不能屈和内收。最有可能瘫痪的肌是","o":["指深屈肌","指伸肌","蚓状肌","骨间侧背肌","骨间掌侧肌"],"a":4,"e":"骨间掌侧肌止于指背腱膜，可屈掌指关节并内收手指，第2骨间掌侧肌作用于环指，故该指不能内收。"},{"q":"某患者左侧舌前2/3味觉障碍，左侧舌下腺、左下颌下腺分泌障碍，左眼不能闭合，左侧额纹消失，左侧鼻唇沟消失，口角偏向右侧。该患者病变可能在","o":["右面神经与脑干相连处","左侧舌神经","左侧面神经","右侧皮质核束","右侧大脑皮质中央前回下1/3"],"a":2,"e":"面神经的特殊内脏运动纤维支配同侧面肌，其鼓索含味觉纤维与副交感纤维，管理舌前2/3味觉及下颌下腺、舌下腺分泌；左侧周围性面瘫合并味觉和腺体分泌障碍，提示左侧面神经主干在面神经管内受损。"},{"q":"患者，女，42岁。被诊断患有颈椎椎管狭窄，行两个椎骨的椎板切除术。下列哪一个韧带最有可能被切除","o":["前纵韧带","齿状韧带","黄韧带","项韧带","十字交叉韧带"],"a":2,"e":"黄韧带连结相邻椎弓板，位于椎板之间、椎管内面，椎板切除术时须切除该韧带以显露椎管。"},{"q":"一男性患者，因脑血管意外收治入院，检查发现左侧大脑中动脉出血。以下症状不会出现的是","o":["对侧鼻唇沟消失","口角偏向同侧","对侧额纹消失","对侧舌肌瘫痪","右侧面肌（眼裂）以下出现瘫痪"],"a":2,"e":"中枢性面瘫只累及对侧睑裂以下面肌，额纹因受双侧皮质核束支配而保留，故不出现对侧额纹消失。"},{"q":"患者因左下颌第三磨牙阻生，需拔除此牙，此牙的牙式是","o":["L7","L8","LⅥ","LⅦ","LⅧ"],"a":1,"e":"牙式以L标示左侧下颌，8代表第三磨牙，故左下颌第三磨牙的牙式记为L8，即该侧智齿。"},{"q":"患者，男，20岁。第1次乘坐飞机，飞机升空中感觉耳部发闷、疼痛，听觉下降。乘务员嘱其做咀嚼运动后好转。与鼓膜两侧气压平衡无关的结构是","o":["鼓室","咽鼓管","鼻咽","外耳道","乳突窦"],"a":4,"e":"鼓膜两侧气压平衡依靠咽鼓管连通鼓室与鼻咽部；乳突窦只连通鼓室与乳突小房，不参与气压平衡。"},{"q":"患者，女，50岁。脊柱骨折，脊髓T10节段受损。患者骨折的椎骨是","o":["T7","T8","T9","T10","T11"],"a":0,"e":"下胸髓节段T9～T12约平对同序数椎骨的上3块，故T10脊髓节段受损时骨折的椎骨为T7。"},{"q":"患者，女，40岁。反复发作的旋转性眩晕、波动性听力下降、耳鸣和耳闷胀感。经检查初步诊断为梅尼埃病，即膜迷路积水。迷路内的液体主要来自","o":["前庭膜","鼓膜","血管纹","壶腹嵴","螺旋膜"],"a":2,"e":"内淋巴由蜗管外侧壁的血管纹、前庭暗细胞及外淋巴滤过产生，血管纹分泌异常致内淋巴生成与吸收失衡，形成膜迷路积水。"},{"q":"患者夜晚长期失眠并伴有白日过度嗜睡，被诊断为昼夜节律调节障碍。可能是什么结构受损引起的","o":["室旁核","漏斗核","背内侧核","视交叉上核","腹内侧核"],"a":3,"e":"视交叉上核接受视网膜传入信息，经下丘脑下行通路调节松果体褪黑素分泌，是机体昼夜节律的起搏中枢。"},{"q":"患者，女，65岁。确诊为乳腺癌。请分析在手术根治术时必须清除的淋巴结是","o":["肘淋巴结","胸骨旁淋巴结","肋间淋巴结","胸肌淋巴结","膈上淋巴结"],"a":3,"e":"乳房外侧部和中央部的淋巴管注入胸肌淋巴结，该群沿胸外侧血管排列于胸小肌下缘，乳癌根治术须将其连同腋淋巴结其他群一并清除。"},{"q":"患者，男，40岁。遇车祸，出现两侧黑眼征，并有鼻出血、脑脊液鼻漏及嗅觉减退或丧失症状，诊断为颅前窝骨折。组成颅前窝的骨包括","o":["额骨眶部、筛骨筛板和蝶骨大翼","额骨眶部、筛骨筛板和蝶骨小翼","额骨眶部、筛骨筛板和蝶骨体","鼻骨、筛骨筛板和蝶骨大翼","额骨鼻部、筛骨筛板和蝶骨大翼"],"a":1,"e":"颅前窝由额骨眶部、筛骨筛板和蝶骨小翼构成，筛板骨折可致鼻出血、脑脊液鼻漏及嗅丝损伤而嗅觉减退。"},{"q":"患者，女，28岁。腰骶部疼痛，后出现下肢力弱、会阴部感觉障碍、尿潴留，怀疑马尾综合征。请问有关马尾的描述正确的是","o":["腰、骶、尾神经根围绕终丝而成","骶、尾神经根围绕终丝而形成","腰、骶神经根围绕终丝而形成","骶神经根围绕终丝而形成","位于椎间孔内"],"a":0,"e":"马尾位于椎管蛛网膜下隙内，由腰、骶、尾三对神经根在脊髓圆锥下方围绕终丝聚集而成。"},{"q":"患者鞍区手术后高热不退，已排除感染因素，高热可能是手术中损伤了","o":["视上核","下丘脑前部","下丘脑后部","室旁核","乳头体核"],"a":1,"e":"下丘脑前区含热敏神经元，体温升高时启动排汗和皮肤血管扩张等散热机制；鞍区手术损毁该区使散热功能丧失，出现中枢性高热，且不伴感染征象。"},{"q":"患者，女，35岁。需实施腰部局麻手术。麻醉药物应注入","o":["硬膜下隙","硬膜外隙","蛛网膜外隙","蛛网膜下隙","终池"],"a":1,"e":"硬膜外隙位于硬脊膜与椎管内壁之间，内含脂肪、静脉丛和淋巴管，腰部麻醉即将药物注入此隙。"},{"q":"患儿，男，3岁。生性活泼。1个月前因感冒滴注某种抗生素，后来发现对外界呼喊其名字时无反应。怀疑为神经性耳聋。进一步检查时应重点考虑检查","o":["外耳道","鼓膜","听小骨链","螺旋器","鼓室"],"a":3,"e":"螺旋器位于蜗管基底膜上，是听觉感受器，药物中毒致毛细胞变性则出现感音神经性耳聋。"},{"q":"患者，男，22岁。因上腹部疼痛1天，加重2小时入院。查体：腹肌高度紧张，全腹压痛明显，上腹为重，肠鸣音减弱。超声检查：仰卧位于上腹腹壁下可见宽约1cm的强回声带，可随体位移动，十二指肠蠕动减弱，左、右髂窝均可见少量不规则无回声区；胰腺因气体遮盖显示不清；肝、胆、脾、双肾未见异常。超声诊断：①上腹腹壁下强回声带；②腹腔积液，考虑为胃穿孔。X线胸片示膈下少量游离气体。治疗行胃大部分切除术时需要结扎的胃右动脉来源于哪条动脉","o":["腹腔干","肝总动脉","脾动脉","胃网膜右动脉","肠系膜上动脉"],"a":1,"e":"胃右动脉起自肝总动脉分支的肝固有动脉，沿胃小弯右行与胃左动脉吻合，供应胃小弯侧的胃壁。"},{"q":"患者，男，40岁。车祸后，锁骨内侧端前方出现疼痛、肿胀、有压痛，首先考虑胸锁关节脱位。X线片确诊为胸锁关节脱位。胸锁关节的组成包括","o":["由锁骨的胸骨端与胸骨的锁切迹及第1肋软骨的上面构成","由锁骨的肩峰端与胸骨的锁切迹及第1肋软骨的上面构成","由锁骨的肩峰端与胸骨的颈静脉切迹及第1肋构成","由锁骨的胸骨端与胸骨角及第1肋构成","由锁骨的肩峰端与胸骨柄构成"],"a":0,"e":"胸锁关节由锁骨的胸骨端与胸骨锁切迹及第1肋软骨的上面构成，是上肢与躯干骨之间唯一的关节。"},{"q":"患者，男，45岁。某影像学诊断为因颅内占位性病变，致颅内压增高，导致小脑幕切迹疝。有关小脑幕切迹疝描述正确的是","o":["脑疝的定义是颅内压增高而引起小脑结构移位","仅有小脑幕后外侧缘形成小脑幕切迹","小脑幕后外侧缘形成小脑幕切迹","小脑幕前内缘游离形成小脑幕切迹","压迫了中脑的大脑脚和滑车神经"],"a":3,"e":"小脑幕呈半月形，其前内侧缘游离，与蝶骨鞍背围成小脑幕切迹，内有中脑通过，疝入时压迫动眼神经和大脑脚。"},{"q":"患者，女，25岁。右下腹痛2小时入院，考虑卵巢囊肿破裂，需要腹腔穿刺以鉴别诊断。下列哪个部位穿刺可能穿出积液","o":["膀胱子宫陷凹","右侧膀胱上窝","右侧腹股沟内侧窝","盲肠后窝","直肠子宫陷凹"],"a":4,"e":"直肠子宫陷凹是女性腹膜腔的最低处，与阴道后穹仅隔阴道后壁和腹膜，积液多积存于此，可经后穹穿刺抽出。"},{"q":"患者，女，29岁。从摩托车上摔下，致颅脑损伤。入院治疗期间出现呼吸急速、咳嗽、心慌、循环衰竭而死亡。分析死亡原因，以下描述正确的是","o":["颅内压降低","中脑呼吸、心跳中枢受损","小脑扁桃体疝","海绵窦血栓","小脑幕切迹疝"],"a":2,"e":"颅后窝容积小，颅内压增高时小脑扁桃体经枕骨大孔疝入椎管，压迫延髓的心血管和呼吸中枢而致呼吸骤停。"},{"q":"某产妇剖宫产后不久出现发热，初步判断为产后腹膜腔感染积液。需做腹膜腔穿刺以明确诊断，穿刺的最佳部位是","o":["直肠前壁","腹前壁","阴道穹前部","阴道穹后部","阴道穹两侧"],"a":3,"e":"阴道穹后部最深，仅隔阴道后壁与直肠子宫陷凹相邻，经此处穿刺可进入腹膜腔抽取积液。"},{"q":"患者，男，20岁。持续高热和腹泻8天，大便每天5～6次，偶尔有黏液，右下腹隐痛。经检查发现肝脏右肋下2cm，脾脏左肋下1cm，躯干背侧隐约可见3颗比米粒小，压之退色的淡红色皮疹。诊断为肠伤寒。伤寒杆菌易侵犯","o":["结肠","空肠","回肠","盲肠","十二指肠"],"a":2,"e":"伤寒杆菌经口入回肠末段，侵入集合淋巴小结引起髓样肿胀、坏死和溃疡，故病变以回肠最显著。"},{"q":"患者，男，60岁。年轻时患过乙型肝炎，近几年常伴有消化不良，食欲缺乏，消瘦无力。B超显示肝内多发结节并伴有腹水。临床上诊断为肝硬化伴有门脉高压。在进行肝门静脉血液分流手术时的连接静脉为","o":["脾静脉与左肾静脉","肝门静脉与左肾静脉","肠系膜上静脉与肠系膜下静脉","肝门静脉与上腔静脉","直肠上静脉与左结肠静脉"],"a":0,"e":"脾肾静脉分流术将脾静脉近端与左肾静脉吻合，使门静脉系血液经脾静脉、左肾静脉流入下腔静脉，从而降低门静脉压力，是常用的门体分流术式。"},{"q":"一患者，因脑部损伤入院治疗。经检查发现该患者左侧下肢不能活动，肌张力增加，但感觉正常。患者损伤的部位为","o":["中央前回上部","中央前回下部","中央前回中部","右侧中央旁小叶前部","中央旁小叶后部"],"a":3,"e":"中央旁小叶前部是对侧下肢的运动代表区，该区病变出现对侧下肢痉挛性瘫痪，未累及感觉区故感觉正常。"},{"q":"患者，男，45岁。因“阵发性头痛，呛咳，耳鸣及走路不稳半年”入院。CT检查示“左脑桥小脑角占位性病变”。经手术治疗，术后病理诊断：舌咽神经鞘瘤。关于舌咽神经的叙述，正确的是","o":["连于脑桥","与舌下神经和副神经同穿颈静脉孔","其咽支分布于咽壁，传导咽壁的感觉","为纯感觉性神经","内脏感觉纤维起自舌咽神经上节"],"a":2,"e":"舌咽神经的咽支与迷走神经的咽支共同构成咽丛，分布于咽壁，传导咽部黏膜的一般感觉。"},{"q":"患者，男，18岁。因车祸入院。主诉在车碰撞中，他弯曲的膝部撞至汽车仪表板上。查体显示组成膝关节的胫骨不稳定，胫骨在股骨下方可向后自由移动。最有可能损伤的结构是","o":["髌韧带","胫侧副韧带","腓侧副韧带","后交叉韧带","前交叉韧带"],"a":3,"e":"后交叉韧带起自胫骨髁间隆起的后方，斜向前上止于股骨内侧髁外侧面，屈膝时最紧张，能防止胫骨向后移位。"},{"q":"患儿，男，10岁。歪头视物半年。测双眼视力正常。临床诊断为左眼上斜肌麻痹。可能出现下列何种症状","o":["左眼瞳孔偏向外上方","左眼瞳孔偏向内上方","左眼瞳孔偏向外下方","左眼瞳孔偏向内下方","左眼瞳孔偏向外侧"],"a":1,"e":"上斜肌使眼球下转、内旋并外展，麻痹后拮抗肌占优势，眼球上转内收，瞳孔偏向内上方。"},{"q":"患儿，男，9岁。因外伤导致左侧肘关节肿胀。X线检查肱骨内上髁附近有明显的骨折线，患者手部尺侧皮肤感觉消失，拇指不能内收，其他四指不能内收。最可能受损的神经是","o":["桡神经","尺神经","腋神经","正中神经","肌皮神经"],"a":1,"e":"尺神经经肱骨内上髁后方的尺神经沟下行，支配小鱼际肌、骨间肌和拇收肌，并分布手尺侧皮肤，损伤后拇指不能内收。"},{"q":"患者，男，45岁。因背部和下肢严重疼痛入院。X线检查显示椎管狭窄综合征。下列哪种情况最有可能出现在MRI检查中","o":["棘上韧带增厚","棘间韧带增厚","前纵韧带增厚","后纵韧带增厚","项韧带增厚"],"a":3,"e":"椎管狭窄多由椎间盘突出、黄韧带肥厚及后纵韧带增厚骨化使椎管矢状径变小所致；后纵韧带贴附于椎体后面构成椎管前壁，增厚时直接压迫硬膜囊与脊髓。"},{"q":"患儿，男，8岁。以呼吸困难，吸气时喉鸣就诊。初步诊断为急性喉阻塞，需在喉部穿刺建立临时通气道。穿刺部位应该是","o":["甲状舌骨膜","方形膜","前庭襞","环甲正中韧带","环状软骨气管韧带"],"a":3,"e":"环甲正中韧带位于环状软骨与甲状软骨之间，位置表浅且无软骨遮挡，为喉阻塞时紧急穿刺的常用部位。"},{"q":"患者，女，39岁。腹痛，发热入院，经诊断为急性腹膜炎。请问患者休息时应采取的体位是","o":["平卧位","半卧位","俯卧位","侧卧位","坐位"],"a":1,"e":"半卧位使腹腔渗液流入盆腔最低的直肠子宫陷凹，减少毒素吸收并利于膈肌运动，为急性腹膜炎的常规体位。"},{"q":"患者，女，70岁。摔倒后无法自主伸小腿。该患者受损的肌是","o":["半腱肌","缝匠肌","股薄肌","股二头肌","股四头肌"],"a":4,"e":"股四头肌是膝关节唯一的伸肌，由股神经支配；该肌功能障碍时不能主动伸直小腿，出现伸膝困难。"},{"q":"患者，男，62岁。于2周前无明显诱因出现间歇无痛性肉眼血尿。B超：膀胱内实质性占位病变。初步诊断为膀胱癌。行手术切除膀胱时需结扎的膀胱上动脉起自","o":["髂外动脉","髂内动脉","阴部内动脉","闭孔动脉","脐动脉"],"a":4,"e":"脐动脉近侧段管腔未闭，发出2～3支膀胱上动脉分布于膀胱上、中部，故膀胱手术时结扎的是膀胱上动脉。"},{"q":"某患者近月来，逐渐出现左侧上、下肢及躯干意识性本体感觉和精细触觉障碍；右侧除外直肌和上斜肌外的所有眼球外肌麻痹，瞳孔散大；左侧上、下肢意向性震颤，共济失调。可能的病变部位及其受损的结构","o":["在左侧中脑上丘高度腹侧部，受损结构有锥体束、内侧丘系、动眼神经根、黑质和小脑上脚","在右侧中脑上丘高度腹侧部，受损结构有锥体束、内侧丘系、动眼神经根、黑质和小脑上脚","在左侧中脑上丘高度被盖内侧部，受损结构动眼神经根、内侧丘系、小脑丘脑纤维和红核","在右侧中脑上丘高度被盖内侧部，受损结构动眼神经根、内侧丘系、小脑丘脑纤维和红核","在右侧中脑下丘高度顶盖背侧部，受损结构滑车神经根、内侧丘系、小脑丘脑纤维和红核"],"a":3,"e":"贝内迪克特综合征累及一侧中脑上丘高度被盖的腹内侧部：动眼神经根受损致同侧除外直肌、上斜肌外的眼球外肌麻痹，红核与小脑丘脑纤维损伤致对侧共济失调。本例右侧动眼神经麻痹、左半身感觉与共济障碍，病灶即在右侧。"},{"q":"患者，女，50岁。查体时叩击髌韧带，观察膝跳反射。与该反射感觉传导相关的结构是","o":["孤束","内侧纵束","薄束","楔束","脊髓丘脑束"],"a":2,"e":"膝跳反射的传入纤维起自股四头肌肌腱的本体感受器，经股神经后根入脊髓后沿薄束上行传导。"},{"q":"患者，男，65岁。偶发血尿1个月来诊，需要排除膀胱肿瘤。膀胱肿瘤的好发部位是","o":["膀胱尖","膀胱底","膀胱体","膀胱颈","膀胱三角"],"a":4,"e":"膀胱三角位于两输尿管口与尿道内口之间，黏膜光滑无皱襞，是肿瘤、结核和炎症的好发部位。"},{"q":"患儿，男，15岁。常规查体时发现无法区分红色和绿色，诊断为红绿色盲。该病发生的解剖学基础是","o":["视锥细胞异常","视杆细胞异常","双极细胞异常","节细胞异常","色素上皮细胞异常"],"a":0,"e":"视锥细胞集中于视网膜中央部，感受强光和颜色；视锥细胞异常使红、绿色觉分辨障碍，形成红绿色盲。"},{"q":"患者，女，49岁。确诊为宫颈癌。术中需要清除的淋巴结是","o":["腹股沟浅淋巴结","闭孔淋巴结","髂总淋巴结","腰淋巴结","腹股沟深淋巴结"],"a":1,"e":"子宫颈的淋巴管沿子宫主韧带注入沿闭孔血管排列的闭孔淋巴结，故宫颈癌根治术须清扫闭孔淋巴结。"},{"q":"患者，男，28岁。经临床诊断，为双眼视野颞侧半偏盲，损伤部位可能是","o":["一侧视神经","一侧视束","一侧视交叉外侧部","视交叉中部","一侧外侧膝状体"],"a":3,"e":"视交叉中部损伤仅累及来自视网膜鼻侧交叉的纤维，故双眼视野颞侧半偏盲，为垂体瘤的典型表现。"},{"q":"患者，女，28岁。乳腺管发生感染，形成乳房脓肿。如行手术切开引流，应尽量选取","o":["横向切口","纵向切口","梭形切口","放射状切口","环形切口"],"a":3,"e":"乳房脓肿切开引流应作以乳头为中心的放射状切口，避免切断乳腺叶间的输乳管而形成乳瘘。"},{"q":"患者因颅内感染，同时伴有瞳孔散大，对光反射和调节反应消失、上睑下垂、眼球固定于外展位。诊断为海绵窦感染，该感染可能累及","o":["视神经","迷走神经","动眼神经","三叉神经","交感神经"],"a":2,"e":"动眼神经穿经海绵窦外侧壁，感染累及后其副交感及躯体运动纤维受损，出现瞳孔散大、上睑下垂和眼球外斜。"},{"q":"患者，女，50岁。缝衣服时不慎针扎小指，与传导该痛觉相关的第3级神经元所在的区域是","o":["腹外侧核","腹后外侧核","腹后内侧核","腹前核","背内侧核"],"a":1,"e":"小指痛觉经脊髓丘脑束上行，终止于背侧丘脑腹后外侧核，该核是躯干四肢浅感觉传导通路的第三级神经元所在。"},{"q":"患者，男，55岁。主诉左侧腹部包块，消化不良。腹部CT显示肿物压迫肠系膜下静脉。推测最可能引起扩张的静脉是","o":["中结肠静脉","右结肠静脉","胰十二指肠下静脉","回结肠静脉","左结肠静脉"],"a":4,"e":"肠系膜下静脉收集左结肠静脉、乙状结肠静脉和直肠上静脉，受压后其属支左结肠静脉回流受阻而扩张。"},{"q":"孕妇，超过预产期2周，仍未分娩，胎盘检查3级成熟。产科医生建议行静脉滴注，加强子宫平滑肌收缩。能促进宫缩的激素是","o":["生长激素","催乳素","黑色细胞刺激素","抗利尿激素","催产素"],"a":4,"e":"缩宫素由下丘脑视上核和室旁核合成、神经垂体释放，能促进子宫平滑肌收缩，可用于加强宫缩引产。"},{"q":"患者，男，50岁。早晨起床时突然出现短暂的天旋地转的感觉，站立不稳，不能行走。经检查初步诊断为耳石症。该症状是脱落的耳石刺激以下哪一结构引起的","o":["壶腹嵴","椭圆囊斑","球囊斑","螺旋器","corti器"],"a":0,"e":"良性阵发性位置性眩晕是椭圆囊斑的耳石脱落后进入膜半规管，头位改变时耳石带动内淋巴流动，刺激壶腹嵴毛细胞，引起短暂的旋转性眩晕与眼震。"},{"q":"患者董某因右侧阴囊部肿胀不适就诊，经检查被诊断为附睾结核。下列关于附睾位置描述正确的是","o":["位于睾丸的上端和前缘","位于睾丸的下端和前缘","位于睾丸的上端和后缘","位于睾丸的下端和后缘","位于睾丸的内侧面"],"a":2,"e":"附睾紧贴睾丸上端和后缘，上端膨大为附睾头，中部为附睾体，下端为附睾尾，睾丸输出小管入附睾头后汇成附睾管。"},{"q":"患者，男，20岁。外伤后自觉腰背痛。X线诊断为第12胸椎压缩性骨折。第12胸椎的形态结构特征是","o":["椎体横断面呈椭圆形","肋凹不典型","棘突短而分叉","上关节突关节面朝向前","横突有横突孔"],"a":1,"e":"胸椎体两侧有与肋头相关节的肋凹，第12胸椎仅与第12肋相关节，肋凹不典型且无横突肋凹。"},{"q":"患者，男，70岁。患有肺气肿。查体胸廓呈“圆桶状”，故称为“桶状胸”。“桶状胸”一般是由于肺内气体含量过多所致。正常的胸廓的形态结构特征是","o":["前后径较左右径短","前后径较左右径长","下窄上宽","成人胸廓近似圆形","分为二口二壁"],"a":0,"e":"正常成人胸廓横径大于前后径，呈前后径较左右径短的扁圆锥形；肺气肿时前后径增大，形成桶状胸。"},{"q":"患者，男，35岁。近日由于车祸入院，经检查后确诊为脑干损伤，主要为内侧丘系损伤。下面关于内侧丘系的叙述，错误的是","o":["内侧丘系的纤维来源于对侧薄束核和楔束核","内侧丘系传导对侧躯干四肢的意识性本体感觉和精细触觉","内侧丘系传导对侧躯干四肢的浅感觉和粗触觉","在延髓，内侧丘系位于锥体背侧","内侧丘系向上经脑干至间脑终止于同侧的背侧丘脑腹后外侧核"],"a":2,"e":"内侧丘系传导对侧躯干四肢的意识性本体感觉和精细触觉，浅感觉与粗触觉由脊髓丘脑束传导。"},{"q":"患者，男，19岁，足球运动员。在比赛中脚着地时，膝部的外侧被撞击，自己不能走路，被送进医院。MRI检查显示胫侧副韧带撕裂。因与韧带附着紧密，下列哪个结构最有可能伴有受伤","o":["半腱肌肌腱","内侧半月板","前交叉韧带","外侧半月板","后交叉韧带"],"a":1,"e":"胫侧副韧带与内侧半月板紧密附着，膝外侧受撞击致韧带撕裂时常连同内侧半月板一并损伤。"},{"q":"患者，男，40岁。右上腹胀痛2个月。肝下缘在右肋弓下3cm。HBsAg阳性。B超检查见肝右叶有一直径5cm的占位病变。AFP检查结果为1200ng/ml。该患者诊断为肝癌的可能性比较大。正常时关于肝的下缘位置的描述正确的是","o":["肝的下界右侧与右肋弓一致","肝的下界右侧在右肋弓下方1cm","肝的下界右侧在右肋弓下方2cm","肝的下界在剑突下不能触及","肝的下界左侧在左肋弓下2cm"],"a":0,"e":"肝下界与肝前缘一致，右侧与右肋弓一致，中部超出剑突下约3cm，左侧被肋弓掩盖，故右肋弓下不能触及肝。"},{"q":"患者，男，35岁。因上腹部间歇性隐痛、进食后饱胀2个月就诊。经胃镜检查并活检诊断为胃癌。关于胃的叙述，错误的是","o":["胃癌多发生于胃底","角切迹是胃小弯的最低处","大部分位于左季肋区","贲门位于第11胸椎体左侧","幽门与十二指肠相通"],"a":0,"e":"胃癌多发生于幽门部即胃窦的小弯侧，胃底并非胃癌好发部位；胃小弯的最低处为角切迹。"},{"q":"患者，女，55岁。蛛网膜下腔出血，出现一侧眼睑下垂时，其动脉瘤的部位可能在","o":["大脑中动脉","前交通动脉","后交通动脉","基底动脉","眼动脉"],"a":2,"e":"后交通动脉与动眼神经紧邻，该处动脉瘤压迫动眼神经内的副交感纤维，早期即出现同侧瞳孔散大和眼睑下垂。"},{"q":"患者，女，38岁。因“经量增多2年余”而入院。体格检查：右侧甲状腺可扪及一结节性肿块。妇科检查：宫颈糜烂，宫体中位，孕2个半月大小，形态不规则，无压痛。超声检查示子宫右前壁突起中低回声79mm×77mm×75mm，左后壁肌层中低回声，直径8mm，右卵巢大小28mm×24mm×19mm，内无回声。诊断：子宫肌瘤。问手术涉及到的子宫动脉的走行及分布","o":["在子宫颈外侧约2cm处从输尿管前方跨越","分布于子宫、卵巢和外阴","在子宫颈外侧约2cm处从输尿管后方跨越","沿子宫体侧缘直线上升至子宫底","主要在子宫阔韧带内走行"],"a":0,"e":"子宫动脉沿子宫侧缘上行，在子宫颈外侧约2cm处越过输尿管的前方，故结扎子宫动脉时须防止损伤输尿管。"},{"q":"患者，男，31岁。呕吐咖啡色胃内物、黑便2天。经检查诊断为上消化道出血。上消化道是指","o":["胃以上的部分","食管以上的部分","十二指肠以上的部分","空肠以上的部分","回肠以上的部分"],"a":2,"e":"临床上以十二指肠为界，口腔至十二指肠的管道称上消化道，空肠及其以下部分称下消化道。"},{"q":"患者，男，21岁，坠落外伤后右侧腰部及全腹部疼痛，无意识丧失，右侧腰部无明显隆起；肾区可疑叩痛，结合其他检查，诊断为外伤性肾蒂离断。肾蒂中的结构不包括","o":["肾动脉","肾静脉","输尿管","肾盂","神经"],"a":2,"e":"肾蒂内自前向后依次为肾静脉、肾动脉和肾盂，并有神经、淋巴管伴行；输尿管起于肾盂下端，不属于肾蒂结构。"},{"q":"患者，男，56岁，因进行性声音嘶哑、食水呛咳10天，右肩臂抬举无力4天就诊。查体：右腭弓低垂，右软腭不能抬举，悬雍垂左偏，右咽反射消失，幕布征阳性。喉镜检查示右声带麻痹。右胸锁乳突肌和斜方肌松弛，轻度萎缩，向左转颈及右侧耸肩力弱。舌肌无萎缩。初步诊断“颈静脉孔综合征”。该患者受损的神经最可能是","o":["舌下神经、舌咽神经和副神经","舌下神经、三叉神经和副神经","舌咽神经、迷走神经和副神经","舌咽神经、三叉神经和副神经","仅有迷走神经"],"a":2,"e":"舌咽神经、迷走神经和副神经自延髓橄榄后沟发出后共同穿颈静脉孔出颅，该孔区病变同时累及三神经，出现吞咽困难、声带麻痹及胸锁乳突肌、斜方肌瘫痪。"},{"q":"患者，男，68岁。感觉肚脐附近的感觉由麻木逐渐过渡至感觉消失。应当首先考虑是什么神经受损伤","o":["第2对胸神经","第4对胸神经","第6对胸神经","第8对胸神经","第10对胸神经"],"a":4,"e":"胸神经前支呈节段性分布，第10胸神经皮支分布于脐平面，故脐周感觉障碍提示第10对胸神经受损。"},{"q":"患者，男，35岁，摔跤运动员。运动时受伤，造成右肩和近侧臂部疼痛难忍，被紧急送往急诊科。在查体期间，患者用他的另一只手抓住受伤侧肘部，无法移动受伤的肢体。影像显示右肩关节脱位。最有可能的表现是","o":["肱骨头向外侧移位","肱骨头向后下移位","肱骨头向前下移位","肱骨头向上后移位","肱骨头向内侧移位"],"a":2,"e":"肩关节囊前下方最薄弱，肱骨头常向前下方脱出，形成最常见的前脱位；患肢呈轻度外展外旋、以健手托肘的保护姿势。"},{"q":"患者，男。排尿困难3年，诊断为慢性膀胱尿潴留。尿道外口狭窄闭塞。进行耻骨上膀胱造瘘的解剖学基础是","o":["膀胱是腹膜间位器官","正常成年人的膀胱体位于耻骨联合上方","老年人的膀胱位置在耻骨联合上方","膀胱尖的位置在耻骨联合上方","膀胱的大小和形态随尿液的充盈不断发生变化，充盈至一定程度，膀胱与腹前壁间的腹膜返折线可以上移至耻骨联合上水平"],"a":4,"e":"膀胱充盈时膀胱尖上升、腹膜返折线上移，膀胱前壁直接贴靠腹前壁，故可在耻骨联合上方穿刺而不经腹膜腔。"},{"q":"患者，女，65岁。有原发性高血压、冠心病史。因胸闷、气短入院。超声检查左室侧壁后壁大面积梗死，拟进行导管术支架治疗。应该治疗以下哪个动脉","o":["对角支","前室间支","旋支","后室间支","右房支"],"a":2,"e":"左心室侧壁与后壁由旋支即左冠状动脉回旋支供血，该支狭窄闭塞致相应区域梗死，故支架应置于旋支。"},{"q":"患者，女，25岁。需产前检查。女性骨盆是胎儿自阴道娩出时必经的骨性产道，其中骨盆内测量对角径的重要标志是","o":["耻骨联合","骶岬","髂骨翼","坐骨棘","尾骨尖"],"a":1,"e":"骶岬为骶骨底前缘中份的突起，是骨盆内测量对角径时确定其后界的骨性标志，经阴道易于触知。"},{"q":"患者，女，45岁。因诊断乳腺癌需要行乳腺癌根治术。术中清扫腋静脉附近的淋巴结时，应注意保护的神经是","o":["胸长神经","肌皮神经","正中神经","腋神经","胸背神经"],"a":4,"e":"胸背神经沿肩胛骨外侧缘伴肩胛下血管下行，分支支配背阔肌，腋淋巴结清扫时最易被损伤。"},{"q":"患者，男，40岁。1年前因头部外伤诊断为滑车神经损伤，患者可能瘫痪的眼球外肌为","o":["上直肌","上斜肌","上睑提肌","外直肌","下斜肌"],"a":1,"e":"滑车神经支配上斜肌，该肌收缩使瞳孔转向下外；神经损伤后眼球不能向外下方转动，并出现复视。"},{"q":"患者，男，45岁。背部被刺伤，半年后检查发现，右侧下肢痉挛性瘫痪、右侧躯干剑突平面以下和右下肢意识性本体感觉丧失，左侧躯干肋弓以下和右下肢痛温觉丧失。试分析脊髓损伤的部位是哪里","o":["T6左侧半","T6右侧半","T8左侧半","T8右侧半","T10右侧半"],"a":1,"e":"脊髓半横断后，损伤平面以下同侧痉挛性瘫痪、深感觉丧失，对侧1～2个节段以下痛、温觉丧失；本例以剑突（T6）为界，故为右侧T6半横断。"},{"q":"患者，女，57岁。体检时发现左侧肩胛骨内侧翘起，尤其在前推重物时明显。应当首先考虑受损的神经是","o":["胸背神经","胸外侧神经","肩胛下神经","胸长神经","胸内侧神经"],"a":3,"e":"前锯肌由胸长神经支配，作用是拉肩胛骨向前并紧贴胸廓；该神经损伤后肩胛骨内侧缘翘起，前推重物时尤为明显，即“翼状肩”。"},{"q":"患者，男，19岁。乘坐电梯参观摩天大厦，当电梯从地面迅速上升时感觉耳部不适，升的越高不适越明显，甚至出现耳内臌胀、疼痛感。这种不适最可能是因为","o":["鼓膜内陷刺激了痛觉神经","鼓膜外凸刺激了痛觉神经","鼓膜内陷刺激了前庭蜗神经","鼓膜外凸刺激了前庭蜗神经","鼓膜受到损伤"],"a":1,"e":"电梯快速上升时外界气压降低，鼓室内压相对升高，鼓膜外凸牵拉刺激痛觉神经末梢引起耳胀痛；咀嚼使咽鼓管开放、气压平衡后缓解。"},{"q":"患者，男，24岁。因街上斗殴被送往医院。影像学检查显示眶下壁骨折。最可能影响的结构是","o":["前群筛窦","后群筛窦","蝶窦","额窦","上颌窦"],"a":4,"e":"眶下壁即上颌窦的顶，骨质菲薄，眼部受击骨折时易累及上颌窦，出现眶下区麻木和鼻出血。"},{"q":"患者因交通事故入院，入院后发现患者左侧瞳孔移向内侧且外展困难，经头颅CT发现患者蝶骨骨折。骨折可能损伤了","o":["动眼神经","滑车神经","眼神经","展神经","眶下神经"],"a":3,"e":"展神经经眶上裂入眶支配外直肌，蝶骨骨折累及眶上裂或海绵窦段时易受损伤；外直肌麻痹后眼球不能外展并偏向内侧，出现复视。"},{"q":"患者，男，30岁。因脊髓空洞症导致双上肢内侧皮肤感觉障碍。可能受损的结构是","o":["孤束","内侧丘系","外侧丘系","三叉丘系","脊髓丘脑束"],"a":1,"e":"官方答案为【内侧丘系】，但依据教材，正确答案为【脊髓丘脑束】。脊髓空洞症破坏白质前连合内交叉的纤维，阻断脊髓丘脑束，出现双侧上肢节段性痛温觉障碍。"},{"q":"患儿，男，10岁。运动时跌到，肘关节呈伸直位并手部撑地，将内上髁撕脱。X线诊断为肱骨内上髁骨折。根据损伤程度分4级，其中第Ⅳ级可伴有神经损伤是因为","o":["内上髁前面的尺神经沟，有尺神经通过","内上髁后面的尺神经沟，有尺神经通过","内上髁后面的腋神经沟，有腋神经通过","内上髁后面的桡神经沟，有桡神经通过","内上髁前面的桡神经沟，有桡神经通过"],"a":1,"e":"尺神经行经肱骨内上髁后方的尺神经沟，内上髁撕脱骨折易挫伤尺神经，出现手内在肌麻痹。"},{"q":"患者，男，73岁。受惊吓后导致暂时性大便失禁。下列哪一神经受损伤后可能会导致大便失禁","o":["内脏大神经","内脏小神经","腰内脏神经","盆内脏神经","迷走神经"],"a":2,"e":"腰内脏神经为交感纤维，经上腹下丛分布至直肠和肛门内括约肌，受损后括约肌张力下降，可致大便失禁。"},{"q":"患者，女，30岁。妇科就诊，经直肠检查，在直肠中部前壁可扪及的结构是","o":["耻骨联合","膀胱","子宫颈","子宫体","阴道"],"a":2,"e":"直肠中段前壁隔直肠阴道隔与子宫颈相邻，经直肠指检可扪及子宫颈和子宫口，为重要的触诊标志。"},{"q":"患者，男，54岁。近日感觉异常来医院就医。经检查为脑干肿瘤，肿瘤位于薄束核与楔束核之间，并已经侵犯两个核。下面关于薄束核和楔束核的叙述，错误的是","o":["传导四肢的本体感觉和精细触觉","在感觉传导通路上属于第二级神经元","发出的纤维组成内侧丘系交叉","发出的纤维经对侧内侧丘系上升","终止于背侧丘脑的腹后内侧核"],"a":4,"e":"薄束核、楔束核是深感觉传导路的第二级神经元，发出纤维交叉后组成内侧丘系，终止于背侧丘脑腹后外侧核，而非腹后内侧核。"},{"q":"患者，男，49岁。由于血尿而就诊。为明确诊断，医生为其行膀胱镜检查。下镜时医生将其阴茎向前上方提拉，关于这一操作，错误的解释是","o":["会使尿道海绵体部位置发生变化","主要影响前尿道的方位","可使耻骨前弯消失","可使耻骨下弯消失","可减轻下镜阻力，减少对尿道的损伤"],"a":3,"e":"耻骨前弯位于耻骨联合前下方，上提阴茎时变直而消失；耻骨下弯位于耻骨联合后下方，位置固定，任何体位都不能使其消失，故该说法错误。"},{"q":"患者，男，21岁。双下肢水肿半年余，反复全身水肿3个月，感冒后水肿加重。尿常规检查尿蛋白呈强阳性，疑有肾实质损害。构成肾实质的结构是","o":["肾皮质和肾髓质","肾皮质和肾柱","肾皮质和肾窦","肾大盏和肾小盏","肾锥体"],"a":0,"e":"肾实质分为浅层的肾皮质和深部的肾髓质，皮质由肾小体与肾小管构成，髓质由15～20个肾锥体组成。"},{"q":"患者，女，25岁。因头部外伤入院。查见右眼眼球下内方斜视，双眼视力正常。可能瘫痪的眼球外肌是","o":["内直肌","上睑提肌","下斜肌","下直肌","上斜肌"],"a":2,"e":"下斜肌由动眼神经支配，收缩使瞳孔转向上外；该肌瘫痪后上斜肌作用占优，眼球固定于下内方，即下内斜视。"},{"q":"患者，男，54岁。因便血就诊。经临床检查诊断为直肠癌，行直肠癌切除术，术后阴茎勃起障碍。应当考虑下列哪一神经受损伤","o":["腰内脏神经","盆内脏神经","内脏大神经","迷走神经","内脏小神经"],"a":1,"e":"盆内脏神经为骶副交感纤维，经盆丛至海绵体血管使其舒张，与阴部神经配合完成阴茎勃起，直肠癌根治术损伤该神经即致勃起障碍。"},{"q":"患者，女，25岁。外伤患者，6个月后说话没有恢复，但能听懂、看懂文字，右手及右臂痉挛性瘫痪，肌张力增高，伸舌偏向右边，无舌肌萎缩，右面下部肌肉瘫痪，整个身体感觉正常。损伤何部","o":["左侧内囊膝部","左侧中央前回下半部","平面神经核平面右侧前份","左侧大脑脚腹侧","左侧中央前回中下部及额下回后部"],"a":4,"e":"左侧中央前回中下部支配右侧上肢及面下部，额下回后部为运动性语言中枢，病变致右上肢瘫、右面下部瘫及运动性失语。"},{"q":"患者，男，21岁。因发热、盗汗伴腹胀半个月入院。查体见体形消瘦，贫血，中量腹水。现需行腹腔穿刺以明确腹水的性质，穿刺的最佳位置是","o":["脐下2cm稍外侧","脐与耻骨联合连线中点","脐与髂前上棘连线的中点","脐与髂前上棘连线的中外1/3交点的稍外方","脐水平与过腹股沟韧带中点的垂线交点"],"a":3,"e":"腹腔穿刺常选脐与髂前上棘连线中、外1/3交点稍外方，此处腹壁薄、无重要器官且避开腹壁下动脉。"},{"q":"患者，女，18岁。拟诊白血病，需进行骨髓穿刺来检查骨髓象。穿刺部位应选择","o":["髂骨","股骨","胸骨","肋骨","椎骨"],"a":0,"e":"髂骨髂后上棘处骨松质丰富、位置表浅，为骨髓穿刺的常用部位，成人胸骨红骨髓已明显减少。"},{"q":"患者，男，20岁。右胸部外伤后就诊。检查发现右侧第4肋骨骨折，右肺呼吸音消失。患者的右肺下界可能","o":["高于左侧肺下界","低于左侧肺下界","与左侧肺下界一样","与受伤前一致","低于受伤前"],"a":0,"e":"右侧第4肋骨折后气体进入胸膜腔致右肺萎陷，肺体积缩小，故右肺下界高于左侧，叩诊呈鼓音。"},{"q":"患者，女，24岁。主诉外伤后伸和外旋大腿能力减弱。损伤的肌是","o":["闭孔外肌","缝匠肌","臀大肌","阔筋膜张肌","半腱肌"],"a":2,"e":"臀大肌起自髂骨翼外面和骶骨背面，止于髂胫束和臀肌粗隆，作用是伸髋并旋外，故其损伤后伸、外旋大腿无力。"},{"q":"患者，55岁。嗜酒多年，近年来记忆力不断下降，行动及对事物的反应迟缓，有时会走路不稳，会出现幻听、幻视。可能是下列哪个结构受损","o":["大脑","小脑","延髓","丘脑","脊髓"],"a":1,"e":"小脑是调节肌张力、协调随意运动和维持平衡的中枢，慢性酒精中毒致小脑皮质浦肯野细胞变性，出现步态不稳、动作迟缓与共济失调，并可伴记忆力减退及精神症状。"},{"q":"患者，男，40岁。因车祸出现肌肩袖撕裂。肌肩袖不包括","o":["冈上肌","肩胛下肌","大圆肌","小圆肌","冈下肌"],"a":2,"e":"肩袖由冈上肌、冈下肌、小圆肌和肩胛下肌的肌腱构成，大圆肌止于肱骨小结节嵴，不参与组成。"},{"q":"患儿，男，15岁。近视800度加150度散光，自述近段时间经常感觉眼中有黑影飘过。受累的结构是","o":["角膜","晶状体","房水","视网膜","玻璃体"],"a":4,"e":"玻璃体为无色透明胶状物，填充于晶状体与视网膜之间；玻璃体混浊时出现眼前黑影飘动，并可影响视力。"},{"q":"患者，女，58岁。劳累后出现心悸气短，近1个月有所加重入院。入院行冠脉造影检查发现后室间支狭窄度85%，拟行支架治疗。关于后室间支正确的是","o":["沿后室间沟下行至心尖","发出房室结动脉","分布于右心房","分布于左心室侧、后壁","分布于室间隔后1/3"],"a":4,"e":"后室间支沿后室间沟下行，分布于室间隔后1/3及左、右心室后壁；房室结动脉多发自右冠状动脉。"},{"q":"患者，男，65岁。突然意识丧失，入院急救。意识恢复后不能说话，右上、下肢不能运动。数日后可以说话，但舌活动不灵活。查体发现：右侧上、下肢痉挛性瘫痪，腱反射亢进，腹壁反射消失，病理反射阳性；伸舌时舌尖偏向左侧，左侧舌肌萎缩；右侧半躯干和右侧上、下肢振动觉和两点辨别性触觉消失，但面部除外；全身痛、温觉正常。可能的病变部位及其受损的结构是","o":["在左侧半延髓锥体交叉高度腹内侧部，受损结构有锥体束和内侧丘系","在左侧半延髓橄榄中部高度腹内侧部，受损结构有锥体束、内侧丘系和舌下神经根","在右侧半延髓橄榄中部高度腹内侧部，受损结构有锥体束、内侧丘系和舌下神经根","在左侧半脑桥下部高度腹侧部，受损结构有锥体束、内侧丘系和三叉神经根","在右侧半脑桥下部高度腹侧部，受损结构有锥体束、内侧丘系和三叉神经根"],"a":1,"e":"左侧延髓橄榄中部腹内侧病变损伤锥体束、内侧丘系和左舌下神经根，出现右偏瘫、右半身深感觉障碍及左舌肌萎缩。"},{"q":"患者，男，34岁。左下腹间歇性绞痛，诊断为输尿管结石。其结石可能嵌顿的位置是","o":["肾实质内","肾小盏","肾大盏","肾盂","输尿管跨髂血管处"],"a":4,"e":"输尿管有三处狭窄，第二狭窄位于小骨盆上口跨髂血管处，管径仅0.2～0.3cm，结石易在此嵌顿并引起绞痛。"},{"q":"患者，男，40岁。患胃溃疡数年。饮酒后诱发胃后壁穿孔，胃内容物流出造成胃后壁及相临结构大片粘连。此时不易累及的器官是","o":["左肾上腺","脾","十二指肠降部","胰","横结肠"],"a":2,"e":"胃后壁隔网膜囊与胰、脾、左肾上腺和横结肠系膜相邻；十二指肠降部位于右侧腹膜外，不与胃后壁毗邻。"},{"q":"患者，女，30岁，因大张口进食，表现为不能闭口，前牙开𬌗，下颌中线偏向健侧，后牙早接触。检查X线可见双侧髁突突出于关节结节前下方，可诊断为颞下颌关节","o":["后脱位","上方脱位","内侧脱","前脱位","外侧脱"],"a":3,"e":"颞下颌关节囊前份薄弱，大张口时下颌头连同关节盘滑至关节结节前方而不能退回，即前脱位。"},{"q":"患者，男，20岁。攀岩时落下肩部着地，造成肱骨小结节骨折。最有可能损伤的结构是","o":["冈上肌","冈下肌","肩胛下肌","小圆肌","喙肱韧带"],"a":2,"e":"肩胛下肌肌腱止于肱骨小结节，该处骨折常伴肌腱撕脱，出现肩关节内旋无力、外旋受限。"},{"q":"患者，男，65岁。因咳嗽、痰中带血就诊入院。诊断为左肺上叶肿瘤。拟通过肺的营养血管实行介入治疗。可能采用的血管是","o":["肺动脉","肺静脉","支气管动脉","支气管静脉","胸主动脉"],"a":2,"e":"支气管动脉是肺的营养血管，随支气管分支进入肺内，经支气管动脉灌注化疗或栓塞是目前肺肿瘤介入治疗的途径。"},{"q":"患者以眶后部疼痛与胀感、视物模糊1个月，视力明显降低2天入院，经颅脑CT检查发现眶区占位性病变。患者出现上述症状，可能是什么神经受损引起","o":["动眼神经","滑车神经","展神经","视神经","眼神经"],"a":3,"e":"视神经穿视神经管入眶，眶内占位压迫视神经致传导障碍，出现视力明显下降和视野缺损。"},{"q":"患者，女，46岁。乳腺癌。乳房皮肤增厚且表面呈“橘皮样”变，是因为病变累及","o":["皮肤","输乳管","输乳管窦","淋巴管","乳腺小叶"],"a":3,"e":"癌细胞阻塞乳房浅淋巴管致淋巴回流受阻、皮肤淋巴水肿，毛囊处皮肤被牵拉下陷，形成“橘皮样”改变。"},{"q":"患者，女，20岁。清晨洗脸照镜时，发现口角歪向左侧，右眼不能紧闭，即来就医。查体可见：右侧额纹消失，右眼不能闭，鼓腮、吹哨时右颊部漏气，右侧口角流口水，右侧鼻唇沟消失，口角偏向左侧。其原因可能是","o":["左侧动眼神经核上瘫","右侧动眼神经核下瘫","左侧面神经核上瘫","右侧面神经核下瘫","右侧展神经核下瘫"],"a":3,"e":"面神经核下瘫表现为同侧全部面肌瘫痪，即额纹消失、眼不能闭合、鼻唇沟变浅、口角歪向健侧；右侧上述表现说明右侧面神经核下受损。"},{"q":"患者因口裂以下皮肤感觉障碍就诊。经颅内CT检查发现其脑干有占位性病变。其感觉障碍可能是由于病变累及什么神经引起的","o":["眼神经","上颌神经","下颌神经","面神经","舌咽神经"],"a":2,"e":"下颌神经为三叉神经第三支，经卵圆孔出颅，其感觉纤维管理颞部、耳前及口裂以下皮肤、口腔底和舌前2/3黏膜的感觉；口裂以下感觉障碍提示下颌神经受累。"},{"q":"患者，男，60岁。诊断为眶内肿瘤。其肿瘤压迫眼眶内结构，其中会引起面部感觉障碍的结构是","o":["视神经","动眼神经","眼神经","滑车神经","展神经"],"a":2,"e":"眼神经为三叉神经第一支，分布于眼球、泪腺及额顶部和鼻背皮肤，受压后出现该区感觉障碍。"},{"q":"患儿，男，6岁。患儿家长约6个月前无意中发现患儿左腹股沟区有1个包块，不痛，扪之质软，平卧或晨起时自行消失，哭闹、咳嗽及用力时出现，并增至乒乓球大小，但无腹痛、呕吐、发热，未作特殊处理，今来院要求住院手术治疗。临床上区分腹股沟斜疝和直疝的标志是","o":["股深动脉","腹壁下动脉","股动脉","面动脉","腹壁浅动脉"],"a":1,"e":"腹股沟斜疝经腹壁下动脉外侧的深环突出，直疝经其内侧的直疝三角突出，故以此动脉为鉴别标志。"},{"q":"患者近1年来刷牙时时常牙龈出血，有口臭，近1个月来右下磨牙处有脓溢出，要求诊治。诊断为牙周炎。牙周炎发生在哪些结构","o":["牙冠、牙质、牙颈","牙质、牙本质、牙髓","牙槽骨、牙釉质","牙周膜、牙槽骨、牙龈","牙髓、牙周膜"],"a":3,"e":"牙周组织包括牙周膜、牙槽骨和牙龈，对牙起保护、固定和支持作用；牙周炎即累及这些支持结构。"},{"q":"患者，女，38岁，已婚。因故实施输卵管结扎手术，结扎部位常选择在","o":["输卵管子宫部","输卵管峡","输卵管壶腹","输卵管漏斗","输卵管伞"],"a":1,"e":"输卵管峡部管腔细、管壁厚、位置固定，为输卵管结扎术的常用部位，壶腹部则为受精场所。"},{"q":"患者，男。诊断为包茎，需手术治疗。手术时，主管医生特别提醒实习医生要注意保护包皮系带。关于包皮系带的描述正确的是","o":["由阴茎海绵体背侧中线的筋膜皱襞形成","由尿道海绵体腹侧中线的筋膜皱襞形成","由阴茎头腹侧中线处的皮肤皱襞形成","由尿道球腹侧中线处的皮肤皱襞形成","阴囊的浅筋膜形成"],"a":2,"e":"包皮系带是阴茎头腹侧中线处由皮肤形成的皱襞，内含阴茎背神经分支，损伤可致阴茎头感觉障碍。"},{"q":"患者，男，18岁。因颈部外伤后出现呼吸、发声功能异常就诊。初步诊断为外伤后喉狭窄。喉软骨中唯一成完整圆环支撑呼吸道的软骨是","o":["甲状软骨","环状软骨","会厌软骨","杓状软骨","喉结"],"a":1,"e":"环状软骨是喉软骨中唯一呈完整环形的软骨，由弓和板构成，支撑呼吸道并保持其通畅，损伤可致喉狭窄。"},{"q":"患者，女，46岁。诊断喉癌，手术欲切除的淋巴结是","o":["下颌下淋巴结","腮腺淋巴结","颏下淋巴结","颈外侧浅淋巴结","气管旁淋巴结"],"a":4,"e":"喉的淋巴主要注入气管前淋巴结和气管旁淋巴结，喉癌根治术需清扫气管旁淋巴结，其肿大可压迫喉返神经致声嘶。"},{"q":"患者，女，40岁。因上颌牙折而就医，需拔牙。牙医操作时，易将断根入上颌窦内的牙齿是","o":["上颌中切牙","上颌第一前磨牙","上颌第一恒磨牙","上颌第三恒磨牙","上颌尖牙"],"a":2,"e":"上颌第二前磨牙及第一、第二磨牙牙根与上颌窦底仅隔薄骨片，有时牙根突入窦腔仅覆黏膜，拔牙断根易推入上颌窦。"},{"q":"患者，男，26岁。因肠穿孔手术治疗后，出现肠梗阻症状，考虑可能有肠袢粘连。其发生原因主要是","o":["腹膜的分泌功能","腹膜的吸收功能","腹膜的支持功能","腹膜的防御功能","腹膜的修复功能"],"a":4,"e":"腹膜渗出纤维蛋白修复受损创面，机化后形成纤维性粘连，是肠袢粘连致肠梗阻的主要原因。"},{"q":"患者，女，35岁。近期出现乏力。入院检查发现有房间隔缺损。房间隔缺损最易发生于哪个部位","o":["卵圆窝","Todaro腱","Koch三角","隔缘肉柱","主动脉隆凸"],"a":0,"e":"卵圆窝处房间隔仅为一层菲薄的膜性结构，缺乏肌性支持，是房间隔缺损最常见的发生部位。"},{"q":"患者，男，40岁。诊断为梗阻性黄疸。需要进行肝内胆管造影，应经哪个部位进行肝穿刺","o":["右肝下间隙","右肝下前间隙","右肝上前间隙","膈下腹膜外间隙","左肝上前间隙"],"a":3,"e":"膈下腹膜外间隙位于肝裸区与膈之间，该处无腹膜覆盖，是肝穿刺行肝内胆管造影的进针部位。"},{"q":"患者，女，18岁。大学入学查体，耳科检查鼓膜时发现鼓膜外侧面正常朝向应该是","o":["向前下外倾斜","向后下外倾斜","向前上外倾斜","向后上外倾斜","向前内下倾斜"],"a":0,"e":"鼓膜位于外耳道底，与外耳道下壁约成45°～50°角，其外侧面朝向前、下、外，检查时据此调整耳镜方向。"},{"q":"患者因头痛、恶心呕吐、视力障碍入院，经诊断为脑积水并伴有视神经盘水肿。颅内高压引起视神经盘水肿的原因是","o":["硬脑膜下隙延伸至视神经周围","脊髓蛛网膜下隙延伸至视神经周围","脑蛛网膜下隙延伸至视神经周围","脊髓硬膜外隙延伸至视神经周围","脊髓硬膜下隙延伸至视神经周围"],"a":2,"e":"视神经由脑向前突出形成，脑的三层被膜及蛛网膜下隙随之延伸包裹视神经，颅内压升高时压力经脑蛛网膜下隙传至视神经周围，引起视神经盘水肿。"},{"q":"患者，女，34岁。车祸后被送往急诊科。影像学检查显示颈椎挥鞭样损伤（反方向猛扭）导致颈椎过伸。此情况下，哪个韧带最有可能受伤","o":["棘上韧带","黄韧带","后纵韧带","前纵韧带","横突间韧带"],"a":3,"e":"颈椎过伸时椎体前缘相互挤压，前纵韧带被过度牵拉，故挥鞭样损伤最易伤及前纵韧带，而后纵韧带与黄韧带相对松弛。"},{"q":"患者，女，68岁。因右眼突然剧烈疼痛、眼红畏光、视物不清，伴有恶心感。诊断为继发性闭角型青光眼。其病因为","o":["房水回流受阻","房水产生过少","房水产生过多","泪液分泌过多","视网膜中央动脉阻塞"],"a":0,"e":"闭角型青光眼因虹膜周边部堵塞房角，房水回流受阻、眼压升高，出现眼痛、眼红、视物不清及恶心。"},{"q":"患者因脑出血入院，经诊断为腹后内侧核出血。该患者可能出现哪种症状","o":["同侧半躯干四肢深感觉丧失","对侧半躯干四肢深感觉丧失","对侧头面部浅感觉丧失","对侧头面部深感觉丧失","同侧头面部深感觉丧失"],"a":2,"e":"腹后内侧核接受三叉丘系纤维，发出丘脑中央辐射投射至中央后回下部，故受损出现对侧头面部痛、温、触压觉障碍。"},{"q":"患者因颅内出血入院，经检查发现患者除颅内高压的症状外还伴有左侧瞳孔不能移向下外。该症状可能是什么神经受损引起的","o":["左动眼神经","左滑车神经","左展神经","右动眼神经","右滑车神经"],"a":1,"e":"上斜肌由滑车神经支配，收缩时使眼球下转、内旋并外展，麻痹后眼球不能转向下外而出现复视。"},{"q":"患者，男，35岁。突然发生剧烈头痛、恶心、呕吐和脑膜刺激征，怀疑蛛网膜下腔出血。需要抽取脑脊液进行诊断，腰椎穿刺抽取脑脊液应在","o":["骶管裂孔处","第5腰椎与第1骶椎棘突间隙","第3腰椎与第4腰椎棘突间隙","第1腰椎与第2腰椎棘突间隙","第12胸椎与第1腰椎棘突间隙"],"a":2,"e":"第1腰椎以下椎管内已无脊髓，仅马尾漂浮于脑脊液中，故在第3、4腰椎间隙穿刺不会损伤脊髓。"},{"q":"患儿，女，5岁。因挖鼻出现一侧鼻出血。最有可能出血的部位是","o":["鼻腔外侧壁上鼻甲处","鼻腔外侧壁中鼻甲处","鼻腔外侧壁下鼻甲处","鼻腔顶","鼻腔内侧壁前下部"],"a":4,"e":"鼻中隔前下部黏膜血管丰富且位置浅表，约90%的鼻出血发生于此区，称易出血区（Little区）。"},{"q":"患者，男，50岁。右手环指被玻璃切割伤，手术中发现屈指浅、深肌腱均断裂。患者的主要表现是","o":["近侧指间关节不能屈曲","远侧指间关节不能屈曲","掌指间关节不能屈曲","两个指间关节不能屈曲","两个指间关节不能屈曲和掌指关节均不能屈曲"],"a":3,"e":"指浅屈肌止于中节指骨，屈近侧指间关节；指深屈肌止于远节指骨，屈远侧指间关节；两腱同时断裂则两个指间关节均不能屈曲，掌指关节仍可屈。"},{"q":"患者，女，30岁。因咽喉部异物感就诊。医生建议做喉镜检查。正常情况下，喉镜检查时如何确定声门裂的位置","o":["位于两侧前庭襞之间","位于两侧声襞之间","位于杓状软骨之间","位于两侧喉室之间","位于方形膜和弹性圆锥之间"],"a":1,"e":"声门裂是两侧声襞与杓状软骨底、声带突之间的裂隙，为喉腔最狭窄处；两侧前庭襞之间的裂隙称前庭裂，较宽，故声门裂位于两侧声襞之间。"},{"q":"患者，男，45岁。左下腹隐痛4个月，近2个月来乏力、消瘦，常有低热。查体：结膜苍白，左下腹部5cm×3cm肿块。化验：血红蛋白95g/L。检查诊断为结肠癌。结肠癌最容易发生的部位在","o":["升结肠","降结肠","横结肠","结肠右曲","乙状结肠"],"a":4,"e":"乙状结肠由乙状结肠系膜连于盆腔左后壁，管腔为结肠最窄处且活动度大，是憩室、扭转和肿瘤的多发部位，故结肠癌以乙状结肠最多见。"},{"q":"患儿，男，3岁。因发热入院。既往患儿多次发生肺炎，发病同时伴随心悸、气短等。心脏彩超检查发现患儿室间隔膜部发生缺损。关于室间隔膜部正确的说法是","o":["室间隔缺损多发生于室间部","分隔右心室流出道与左心室流入道","后上部分隔右心室与左心房","占室间隔的1/2","借二尖瓣前瓣分为两部"],"a":0,"e":"室间隔膜部位于室间隔上部，其后上部分隔右心房与左心室，下部为室间部；膜部缺乏肌性支持，是室间隔缺损最常见的部位。"},{"q":"一个年轻的女患者足内侧缘皮肤被大头针刺伤肿胀，请问肿大的淋巴结是","o":["腹股沟浅淋巴结上群","腘淋巴结","腹股沟深淋巴结","腹股沟浅淋巴结下群","髂外淋巴结"],"a":3,"e":"足内侧缘及小腿内侧的淋巴管沿大隐静脉上行，注入腹股沟浅淋巴结下群，刺伤后该群淋巴结肿大。"},{"q":"肛门、会阴部手术时，患者取左侧卧位，弯腰低头曲背，两手抱膝。医生采用骶管麻醉技术，将麻醉药物注入骶管。骶管麻醉的体表标志是","o":["骶岬","骶粗隆","骶角","尾骨尖","骶后孔"],"a":2,"e":"骶管裂孔两侧有向下突出的骶角，活体可扪及，是骶管穿刺时定位和判断进针点的体表标志，骶管麻醉即经骶管裂孔刺入骶管。"},{"q":"小李由于不育而就诊，医生检查后发现其为先天性输精管缺失患者。下列关于输精管的描述错误的是","o":["起于附睾尾","末端变细与精囊排泄管汇合形成射精管","睾丸部位于睾丸前缘","精索部为男性节育手术理想位置","腹股沟部位于腹股沟管内"],"a":2,"e":"“睾丸部位于睾丸前缘”的说法错误，输精管睾丸部始于附睾尾，沿睾丸后缘、附睾内侧上行至睾丸上端；精索部位置表浅，是结扎的理想部位。"},{"q":"患者，男，20岁。在跑步和爬山时，不能屈和内旋小腿。最有可能受损的肌是","o":["股二头肌","缝匠肌","股直肌","股中间肌","阔筋膜张肌"],"a":1,"e":"缝匠肌起自髂前上棘止于胫骨上端内侧面，可屈髋、屈膝并使小腿内旋，为该动作的主要肌。"},{"q":"患者，男，31岁。手掌因大钉子的穿透伤导致腱鞘炎。检查发现腱鞘尺骨囊感染。这种感染最有可能导致坏死的肌腱是","o":["尺侧腕屈肌的肌腱","拇长屈肌腱","指深屈肌腱","桡侧腕屈肌腱","掌长肌腱"],"a":2,"e":"尺侧囊包绕指浅、指深屈肌腱，腱鞘感染积脓使腱内压升高、血供受阻，位置深在的指深屈肌腱最易坏死。"},{"q":"患者，男，40岁。突发右上腹阵发性绞痛，伴恶心、呕吐。右上腹出现压痛和肌紧张，墨菲征阳性，诊断为急性胆囊炎。请问在体格检查时于何处可经腹前壁触及胆囊底","o":["右腹直肌内侧缘与右肋弓交点处","左腹直肌外侧缘与左肋弓交点处","右锁骨中线与右肋弓交点处","脐与髂前上棘连线的中、外1/3交点处","剑突下靠右侧1～2cm"],"a":2,"e":"胆囊底在右锁骨中线与右肋弓交点处贴近腹前壁，胆囊炎时该处压痛，为Murphy征的检查部位。"},{"q":"患者，男，69岁。因舌右侧颜色异常及运动不便就诊。检查发现患者伸舌无力且舌尖偏向右侧。患者3年前曾因右扁桃体恶性肿瘤行根治性颈清扫术。患者最可能损伤了","o":["三叉神经","面神经","舌咽神经","舌神经","舌下神经"],"a":4,"e":"舌下神经支配全部舌内肌和大部分舌外肌，右侧损伤后右半舌肌瘫痪萎缩，伸舌时舌尖偏向患侧。"},{"q":"患儿，2岁。因先天性斜颈入院需手术矫正。在颈部手术暴露胸锁乳突肌时，注意勿伤到的静脉是","o":["颈内静脉","颈外静脉","锁骨下静脉","面静脉","颈前静脉"],"a":1,"e":"颈外静脉沿胸锁乳突肌浅面下行，与该肌关系密切，暴露胸锁乳突肌时易被损伤，且损伤后可致气栓。"},{"q":"患者，男，68岁。因进行性吞咽困难就诊。经食管镜检查，发现距中切牙约25cm处有一肿块，进行活检，诊断为食管癌。请问该患者的肿块位于食管哪个部位","o":["食管颈部","食管第1个狭窄","食管第2个狭窄","食管第3个狭窄","食管腹部"],"a":2,"e":"食管第二狭窄位于左主支气管后方与其交叉处，相当于第4、5胸椎之间，距中切牙约25cm。"},{"q":"患者，女，45岁。因咳嗽半个月余，突发剧烈胸痛伴呼吸困难4小时前来就诊。患者半个月前因受凉感冒后出现咳嗽伴少许白色黏痰，自服感冒、镇咳药无明显好转。曾就诊于社区医院，行X线胸片检查未发现明显异常，左肺纹理增粗。给予抗感染治疗，咳嗽较前稍有减轻，4小时前无明显诱因突觉胸痛，呼吸费力，遂卧床休息片刻不见好转，且有加重趋势，由家人急送来医院。夜间急诊行胸部X线检查仍发现左肺纹理增粗。余未见异常。无异物史。一般情况可，遂留院观察。给予吸氧，病情无明显好转，2小时前胸痛及呼吸困难程度进行性加剧，再次行胸部X线检查发现左侧全肺不张，余未见异常，遂收入院。次日，肺CT检查结果示左肺不张，余无异常。行纤维支气管镜检查于主支气管隆突偏左处发现一新生物，占满整个左主支气管腔，至此诊断明确，左中心型肺癌。同时取活检数块，送病理，结果证实为小细胞未分化癌。问：手术治疗过程中需涉及到的胸主动脉，下列关于其说法错误的是","o":["平胸骨角高度续于主动脉弓","穿主动脉裂孔续为腹主动脉","下端位于下腔静脉的左侧","胸主动脉的脏支较为粗大","胸主动脉属后纵隔器官"],"a":3,"e":"胸主动脉壁支如肋间后动脉粗大，脏支如支气管动脉、食管动脉细小；它平第4胸椎续于主动脉弓，穿主动脉裂孔续为腹主动脉。"},{"q":"患者，女。停经3个月以上，基础体温单相。妇科检查子宫偏小，阴道脱落细胞涂片、宫颈黏液检查显示体内雌激素作用水平偏低，子宫内膜呈增生反应。血卵泡刺激素（FSH）、黄体生成素（LH）水平偏低或LH/FSH比值＜3，血催乳素（PRL）正常水平。可能是什么结构病变引起的","o":["下丘脑-垂体-肾上腺轴系","下丘脑-垂体-甲状腺轴系","下丘脑-垂体-性腺轴系","下丘脑脊髓束","背侧纵束"],"a":2,"e":"闭经伴雌激素水平低、FSH与LH均低而PRL正常，提示下丘脑-垂体-性腺轴功能低下，属中枢性闭经。"},{"q":"患儿，男，16岁。右上磨牙疼痛2周后，出现头痛、鼻腔分泌物增多、鼻塞等表现。最有可能累及的结构是","o":["额窦","上颌窦","筛窦前群","筛窦中群","筛窦后群"],"a":1,"e":"上颌窦底壁即上颌骨牙槽突，与上颌第二前磨牙及第一、二磨牙根间仅隔薄骨片，牙根感染可直接蔓延至窦内；窦口位置高、引流不畅，故牙痛后易继发上颌窦炎。"},{"q":"患者，男，28岁。因视觉异常入院。瞳孔对光反射检查，无论光照哪一侧瞳孔，患侧的瞳孔直接及间接对光反射都消失，但健侧的瞳孔对光反射都存在。损伤了","o":["健侧的动眼神经","健侧的视神经","视交叉","患侧的动眼神经","患侧的视神经"],"a":3,"e":"一侧动眼神经受损使瞳孔括约肌的传出中断，无论光照哪一侧，患侧瞳孔直接、间接对光反射均消失，健侧正常。"},{"q":"患者，男，72岁。翼点处受外力而骨折，诊断为“硬膜下血肿”。损伤的血管是","o":["颞板障静脉","脑膜中动脉前支","脑膜中动脉后支","大脑中动脉","颞深动脉"],"a":1,"e":"翼点处骨板最薄，其内面有脑膜中动脉前支经过的血管沟，颞部骨折易撕破该支，形成硬膜外血肿。"},{"q":"患者，男，20岁。鼻部外伤后出现嗅觉功能异常。有可能受损的部位是","o":["上鼻甲","中鼻甲","下鼻甲","鼻中隔下部","鼻前庭"],"a":0,"e":"嗅区位于上鼻甲及其相对的鼻中隔和鼻腔顶部，富含嗅细胞，鼻部外伤累及该区即出现嗅觉异常。"},{"q":"患者因面部针刺样疼痛就诊，经检查发现其疼痛部位位于眼裂以上，每次疼痛持续数秒，且可由眨眼激发。诊断为三叉神经痛。请问具体是三叉神经哪一支分支引起的","o":["眼神经","上颌神经","下颌神经","面神经","舌咽神经"],"a":0,"e":"眼神经为三叉神经第一支，经眶上裂入眶后分出额神经、泪腺神经和鼻睫神经，分布于眼裂以上的额顶部、眼及鼻背皮肤；故眼裂以上的发作性剧痛属眼神经痛。"},{"q":"患者，男，66岁。因滑倒导致左侧肩部疼痛，肿胀，左肩主动活动功能受限。X线检查显示左侧肱骨外科颈附近有明显的骨折线，最容易受损伤的神经是","o":["腋神经","肌皮神经","正中神经","尺神经","桡神经"],"a":0,"e":"腋神经与旋肱后血管伴行，绕肱骨外科颈至三角肌深面，外科颈骨折最易损伤该神经，致三角肌瘫痪和“方肩”。"},{"q":"患者，男，62岁。腹泻，便血。经结肠镜检查诊断为大肠息肉和憩室。大肠息肉和憩室好发于","o":["升结肠","横结肠","降结肠","乙状结肠","盲肠"],"a":3,"e":"乙状结肠肠腔较窄、粪便停留时间久，黏膜受刺激时间长，是大肠息肉和憩室的好发部位。"},{"q":"患者，男，65岁。因跌倒并手、肘着地后，右肩出现局部肿胀、疼痛、压痛，肩关节活动功能障碍，上臂上段瘀斑。X线可见肱骨解剖颈下2～3cm处的骨折。提示是","o":["肱骨大结节骨折","肱骨小结节骨折","肱骨解剖颈骨折","肱骨外科颈骨折","肱骨头骨折"],"a":3,"e":"肱骨外科颈位于解剖颈下2～3cm，为骨松质与骨密质交界处，此处骨折可伴腋神经损伤。"},{"q":"患者，男，23岁。跌倒时上肢外展外旋，手掌或肘部着地，外力沿肱骨纵轴冲击，肩关节囊的下壁相对最为薄弱，肱骨头自肩胛下肌和大圆肌之间薄弱部撕脱关节囊，向前下脱出，最易形成肩关节","o":["喙突下脱位","后脱位","锁骨下脱位","肩胛冈下脱位","肩峰下脱位"],"a":0,"e":"肩关节前下方关节囊薄弱，肱骨头经肩胛下肌与大圆肌之间脱出并停留于喙突下方，形成喙突下脱位。"},{"q":"患儿，女，15岁。左侧手掌因为刀伤后导致拇指不能内收。可能损伤的神经是","o":["桡神经","尺神经","正中神经","肌皮神经","腋神经"],"a":1,"e":"拇收肌由尺神经深支支配，尺神经损伤后拇指不能内收，常伴骨间肌萎缩和夹纸试验阳性。"},{"q":"患者，女，56岁。无明显诱因出现左侧瞳孔变大，且左眼视力下降，尤其看近物模糊。检查左侧瞳孔对光反射障碍。首先考虑下列哪种结构受损","o":["三叉神经的分支眼神经","动眼神经核","滑车神经","动眼神经的交感纤维","动眼神经的副交感纤维"],"a":4,"e":"动眼神经副交感纤维经睫状神经节换元后支配瞳孔括约肌和睫状肌；受损后瞳孔散大、对光反射消失，看近物模糊。"},{"q":"患者，男，57岁。摔倒时肘关节处于伸直位，手掌着地。检体发现肘部肿胀和有压痛。X线诊断为尺骨鹰嘴骨折。鹰嘴的形态特征是","o":["肱骨滑车后上方的突起","尺骨滑车切迹后上方的突起","桡骨滑车切迹后上方的突起","尺骨滑车切迹前下方的突起","肱骨滑车前下方的突起"],"a":1,"e":"鹰嘴是尺骨滑车切迹后上方的突起，为肱三头肌肌腱的止点，伸肘时嵌入肱骨鹰嘴窝，体表可触及。"},{"q":"患者，男，65岁。患者自诉于13小时前无明显诱因出现腹部疼痛，呈阵发性胀痛，无放射性及刀割样疼痛，伴恶心、呕吐3次，为非喷射性呕吐，呕吐物为胃内容物及胃液，每次量约50ml，无咖啡样物，无畏寒、发热，无腹泻，无尿痛、解肉眼血尿。发病后在家口服草药治疗，具体不详，但患者腹痛、腹胀无缓解，于今为求进一步治疗而来我院就诊，门诊医师行腹部正位片检查后，拟肠梗阻收入我科。发病以来患者精神一般，食欲、睡眠欠佳，小便正常，解1次黄色成形便，量约20g，无黏液脓血便。行手术腹腔探查术，术中发现部分小肠坏死，需切除。需结扎的空、回肠动脉来源于","o":["肠系膜下动脉","腹腔干","脾动脉","肠系膜上动脉","胃网膜左动脉"],"a":3,"e":"空、回肠的动脉为空肠动脉和回肠动脉，均发自肠系膜上动脉，在肠系膜内反复分支形成弓状吻合。"},{"q":"患者，男，40岁。中上腹饥饿性隐痛反复发作10年，伴反酸，嗳气，进食和服用抑酸剂可缓解。该患者最可能的疾病是消化性溃疡，好发部位是胃的","o":["贲门部","贲门切迹","幽门部","胃底","胃体"],"a":2,"e":"胃溃疡多位于幽门部小弯侧，该处黏膜与黏膜下层紧贴、血供相对较差，为消化性溃疡的好发部位。"},{"q":"患者，男，68岁。因咳嗽，痰中带血就诊。有25年吸烟史。经检查后初步诊断为肺癌，伴有胸腔积液。胸腔积液最先积聚的部位是","o":["肺门","斜裂","肺下缘","肋膈隐窝","肋纵隔隐窝"],"a":3,"e":"肋膈隐窝由肋胸膜与膈胸膜返折形成，位置最低、容量最大，深吸气时肺缘也不能伸入其内，故胸膜腔积液最先积存于此。"},{"q":"患者，男，55岁。自己无意间发现颈前部单个肿块，表面光滑，边界清楚，无压痛，可随吞咽上下移动。入院经B超等检查，诊断为“甲状腺腺瘤”。行甲状腺次全切除术，术后出现声嘶及发声无力。该患者出现上述症状最可能的原因是","o":["术中损伤声韧带","术中损伤喉上神经外支","术中损伤喉上神经内支","术中损伤单侧喉返神经","术中损伤单侧舌咽神经"],"a":3,"e":"单侧喉返神经支配除环甲肌以外的全部喉肌，损伤后声带麻痹、声音嘶哑；喉上神经外支损伤仅致音调降低。"},{"q":"患儿，女，12岁。因受凉，自诉咳嗽，咽疼，耳部发闷。对耳部不适这一现象的解释不正确的是","o":["鼓膜两侧空气压力失去平衡","鼓室暂时成密闭的室腔，与外界不交通","咽鼓管炎症、水肿，导致咽鼓管闭塞","外耳道堵塞","咽鼓管咽口平时处于关闭状态"],"a":3,"e":"耳闷源于鼓室与外界气压失衡：咽鼓管咽口平时关闭，炎症水肿使其闭塞，鼓室空气被吸收形成负压；与外耳道堵塞无关。"},{"q":"患者，男，35岁。慢性中耳炎患者。最近出现阵发性或激发性眩晕，偶伴恶心、呕吐等症状，多在身体姿势改变时发作。该患者病变最可能累及了","o":["颅内","迷路","颈内静脉","鼓膜","乳突窦"],"a":1,"e":"膜迷路内的位觉感受器即椭圆囊斑、球囊斑和壶腹嵴受累，体位改变时诱发眩晕并伴恶心、呕吐。"},{"q":"患者，女，47岁。手术中损伤椎动脉后出现左侧上下肢瘫痪，右侧眼外直肌麻痹。请问该患者可能损伤了以下哪个结构","o":["右侧锥体束和右侧动眼神经","右侧锥体束和左侧展神经","左侧锥体束和右侧展神经","右侧锥体束和右侧展神经","左侧锥体束和左侧展神经"],"a":3,"e":"锥体束在脑桥基底部下行后交叉支配对侧肢体，展神经根自脑桥下部穿出，故右侧病变致左侧偏瘫和右眼外直肌麻痹。"},{"q":"松果体瘤患者出现大量排尿，尿比重在1.005以下，尿在4000ml/d以上，可能是因为肿瘤侵犯了","o":["下丘脑脊髓束","乳头被盖束","乳头丘脑束","前脑内侧束","视上核或视上核垂体束"],"a":4,"e":"视上核及视上核垂体束合成、运输抗利尿激素，受损后激素缺乏，出现尿崩，尿量剧增而比重降低。"},{"q":"患儿，3岁。急性中耳炎后出现乳突部皮肤肿胀、潮红，有明显压痛，诊断为乳突炎。中耳炎症经何处蔓延至乳突","o":["乳突窦","乳突小房","听小骨链","蜗窗","咽鼓管"],"a":0,"e":"乳突窦是鼓室向后上的延续，经乳突窦口与鼓室相通，中耳炎可经此蔓延至乳突小房引起乳突炎。"},{"q":"患者因颅内血肿入院，经影像学检查判断血肿位于颅前窝，患者有可能出现什么症状","o":["视觉受损","眼球外展受限","对光反射消失","嗅觉障碍","面部浅感觉障碍"],"a":3,"e":"颅前窝底主要由筛板构成，嗅丝穿筛孔入颅，骨折累及筛板时撕脱嗅丝而致嗅觉障碍，并可伴脑脊液鼻漏。"},{"q":"患儿，男，5岁。因异物进入呼吸道需紧急进行支气管镜检查。进行支气管镜检查时，看到下列哪个结构，可判断已经到达气管末端","o":["第4胸椎","胸骨角","气管隆嵴","气管衩","气管软骨"],"a":2,"e":"气管杈内面有矢状位向上凸出的半月状嵴称气管隆嵴，略偏向左侧，是支气管镜检查时判断气管末端及左、右主支气管分叉的重要标志。"},{"q":"患者，男，76岁。中风后右半身不能动2周，既往有高血压史。查体：左眼瞳孔开大，并转向外下方，瞳孔直接对光反射消失，上睑下垂；右侧上、下肢呈痉挛性瘫痪，腱反射亢进，病理反射阳性，并伴有睑裂以下面瘫；伸舌时舌尖偏向右侧，肌不萎缩。其原因可能是","o":["左侧半中脑上丘高度大脑脚底受损","右侧半中脑上丘高度大脑脚底受损","左侧半中脑下丘高度大脑脚底受损","右侧半中脑下丘高度大脑脚底受损","左侧半中脑下丘高度被盖部受损"],"a":2,"e":"左侧中脑下丘高度大脑脚底病变损伤锥体束和动眼神经根，出现右偏瘫、右面下部及舌肌中枢性瘫伴左瞳孔散大、上睑下垂。"},{"q":"患儿，男，8岁。自诉黄昏或较暗光线下看不清东西，并暗适应障碍。诊断为视网膜色素变性（夜盲症）。这是由何种细胞功能不良引起的","o":["色素上皮细胞","节细胞","视锥细胞","视杆细胞","双极细胞"],"a":3,"e":"视杆细胞含视紫红质，司弱光觉，其功能障碍时暗适应能力下降，在暗处视物不清而出现夜盲。"},{"q":"患者，男，53岁。手术中损伤椎动脉后出现右侧头面部痛温觉障碍。请问该患者可能损伤了","o":["左侧薄束","左侧锥体束","左侧三叉神经脊束","右侧三叉神经脊束","右侧锥体束"],"a":3,"e":"三叉神经脊束位于延髓外侧区，传导同侧头面部痛、温觉；椎动脉的延髓支供应此区，受损后即出现同侧头面部痛温觉障碍，而对侧肢体感觉不受影响。"},{"q":"患者因瞳孔缩小、眼睑下垂、眼球内陷、患侧额部无汗就诊。经检查判断为Honer综合征。其上睑下垂的症状需与哪个脑神经损伤相鉴别","o":["面神经","动眼神经","滑车神经","眼神经","展神经"],"a":1,"e":"Horner综合征的上睑下垂由上睑板肌瘫痪所致，程度较轻；动眼神经损伤时提上睑肌瘫痪，上睑下垂明显。"},{"q":"患者，女，58岁。腹痛，高热寒战，黄疸。经检查诊断为胆管结石。不属于肝外胆道的结构是","o":["肝管","肝总管","胆小管","胆囊","胆总管"],"a":2,"e":"肝外胆道系统指肝门以外的胆道，包括肝左管、肝右管、肝总管、胆囊和胆总管；胆小管位于肝小叶内，是肝细胞分泌胆汁的微细管道，属肝内胆道。"},{"q":"患者，男，60岁。手术后肛门失禁，可能损伤了肛门外括约肌的哪部分","o":["浅部","皮下部","深部","浅部和深部","皮下部和浅部"],"a":3,"e":"肛门外括约肌的浅部和深部与直肠下份纵行肌、肛门内括约肌、肛提肌共同构成肛直肠环，为控制排便的重要肌束，手术损伤此环即致大便失禁；皮下部切断则不引起失禁。"},{"q":"患者，男，40岁，建筑工人。被一个混凝土块砸在腿上，随后不能跖屈踝关节和足内翻。最有可能受损的肌是","o":["趾长伸肌","胫骨前肌","胫骨后肌","腓骨长肌","腓骨短肌"],"a":2,"e":"胫骨后肌起自小腿骨间膜后面，止于足舟骨粗隆，作用是使足内翻并协助跖屈；该肌瘫痪则不能跖屈踝关节和足内翻。"},{"q":"患者，男。自述车祸后出现右眼眼球向内斜视。可能受累的神经是","o":["动眼神经","视神经","滑车神经","展神经","眼神经"],"a":3,"e":"展神经支配外直肌，损伤后外直肌瘫痪，拮抗的内直肌占优势，出现眼球内斜、外展受限。"},{"q":"患者，男，30岁。因中耳炎入院。经检查发现患者舌前2/3味觉传导障碍。其炎症可能损伤了什么结构","o":["舌下神经","鼓索","舌咽神经","岩小神经","岩大神经"],"a":1,"e":"鼓索在面神经出茎乳孔前发出，经鼓室穿岩鼓裂加入舌神经，其味觉纤维随舌神经分布于舌前2/3味蕾；中耳炎波及鼓索即致舌前2/3味觉障碍。"},{"q":"患者，女，38岁。颈部发现一包块，并伴有声音嘶哑。经医生诊断为甲状腺囊肿。在甲状腺切除手术中，误伤了甲状旁腺，可导致以下哪些症状","o":["仅钙代谢失常","手足搐搦症","仅磷代谢失常","血钙浓度升高","血磷浓度降低"],"a":1,"e":"甲状旁腺分泌甲状旁腺激素调节钙磷代谢，甲状腺手术误伤后血钙降低、神经肌肉兴奋性增高，出现手足搐搦。"},{"q":"患者，女，32岁。在足球比赛中受伤，后被送入医院。在骨科诊所接受坐姿检查，医生双手握住右胫骨，可以在股骨下端将右胫骨移向后方，左胫骨不能以这种方式移动。右膝最有可能受伤的结构是","o":["前交叉韧带","腓侧副韧带","胫侧副韧带","内侧半月板","后交叉韧带"],"a":4,"e":"后交叉韧带在屈膝时最紧张，能防止胫骨向后移位；其断裂后胫骨可被推向后，出现后抽屉试验阳性。"},{"q":"患者，女，50岁。因中枢性眩晕和眼球震颤就医。可能与以下哪个神经核相关","o":["楔束核","薄束核","前庭神经核","蜗神经核","孤束核"],"a":2,"e":"前庭神经核接受前庭神经传入，并与眼球运动核及脊髓联系，受损出现眩晕、眼球震颤和平衡障碍。"},{"q":"某高血压患者，昏迷数小时后清醒。查体发现：右侧上、下肢呈痉挛性瘫痪，腱反射亢进，病理反射阳性；伸舌时舌尖偏向左侧，左侧半舌肌萎缩不明显；右侧躯干及上、下肢振动觉和精细触觉消失，但全身痛、温觉正常。试分析可能损伤的部位及结构是","o":["左侧中脑腹侧部，受损结构有左侧锥体束、右侧内侧丘系","左侧脑桥腹侧部，受损结构有左侧锥体束、右侧内侧丘系","右侧脑桥腹侧部，受损结构有右侧锥体束、左侧内侧丘系，左侧三叉神经核","左侧延髓腹侧部，受损结构有左侧锥体束、左侧内侧丘系，左侧舌下神经核","右侧延髓腹侧部，受损结构有右侧锥体束、右侧内侧丘系，右侧舌下神经核"],"a":3,"e":"左侧延髓内侧部病变累及左侧锥体束、左侧内侧丘系及左侧舌下神经根，出现对侧偏瘫、对侧深感觉障碍和同侧舌肌瘫痪，伸舌偏向患侧。"},{"q":"患者，女，32岁。因刀伤导致左侧下肢行走困难，膝跳反射消失，大腿前面和小腿内侧面皮肤感觉消失。应该考虑受损伤的神经是","o":["闭孔神经","股神经","坐骨神经","胫神经","腓总神经"],"a":1,"e":"股神经支配股四头肌及大腿前面、小腿内侧面皮肤，并参与膝跳反射，损伤后伸膝无力、反射消失伴该区感觉障碍。"},{"q":"患者，男，23岁。于入院前2个月余出现腹泻，平均每天10余次。1个月前无明显诱因出现暗红色血便。结肠镜检查：距肛门8cm直肠狭窄，可见溃疡型肿物。活检病理诊断：直肠癌。直肠癌不容易侵及以下哪个器官","o":["前列腺","膀胱","睾丸","精囊","输尿管"],"a":2,"e":"直肠前壁借腹膜返折与膀胱、精囊和前列腺相邻，后方为骶骨，睾丸位于阴囊内，与直肠无毗邻关系。"},{"q":"患者，男，66岁。双眼对光反射消失。其受损部位最可能在","o":["两侧视区","两侧视辐射","顶盖前区","两侧外侧膝状体","双侧动眼神经核"],"a":2,"e":"顶盖前区是瞳孔对光反射的中枢，接受双侧视束纤维后发出纤维至两侧动眼神经副核；该区受损则双眼对光反射均消失。"},{"q":"患者，男，78岁。无明显诱因近期感觉双下肢皮肤干燥，汗腺分泌障碍。下列哪一结构受损可能导致此类症状","o":["颈神经节","胸神经节","腰神经节","奇神经节","星状神经节"],"a":2,"e":"腰神经节发出的节后纤维随腰丛血管至下肢，支配汗腺和血管，受损后下肢皮肤干燥、汗腺分泌障碍。"},{"q":"患者，男，58岁。无痛性血尿半年，被诊断为肾肿瘤。需行肾部分切除术，手术时需缝合的结构是","o":["纤维囊","肾前筋膜","肾后筋膜","脂肪囊","腹膜脏层"],"a":0,"e":"纤维囊为紧贴肾表面的固有被膜，肾部分切除后缝合此层可闭合创面、固定残肾并防止出血。"},{"q":"患者，男，62岁，因肺癌行一侧全肺切除术，术中不需要切断的结构是","o":["肺动脉","肺静脉","主支气管","支气管动脉","段支气管"],"a":4,"e":"全肺切除需在肺门处切断肺动脉、肺静脉和主支气管，并结扎支气管动脉；段支气管位于肺叶内，随患肺一并切除，无需单独处理。"},{"q":"患者，女，28岁。异位妊娠并发输卵管破裂出血。行阴道后穹窿穿刺确诊，穿刺到达的部位是","o":["直肠","输卵管","直肠子宫陷凹","膀胱子宫陷凹","直肠膀胱陷凹"],"a":2,"e":"阴道穹后部最深，与直肠子宫陷凹仅隔阴道壁，穿刺即达该陷凹，可抽出腹腔内积血，为异位妊娠的常用诊断途径。"},{"q":"患者，男，55岁。主诉夜间呕血100ml左右，食欲缺乏，消瘦。曾有乙型肝炎病史。B超显示肝缩小，肝内回声增粗，脾大。此患者呕血是由于哪条静脉破裂所致","o":["气管静脉","食管静脉","左胃静脉","右胃静脉","肠系膜上静脉"],"a":1,"e":"肝硬化门静脉高压时胃左静脉与奇静脉间的食管静脉丛曲张，破裂后引起呕血和黑便，是上消化道大出血的常见原因。"},{"q":"患者，男，37岁。行颈后三角区淋巴结活检术后出现平静时下颏转向右侧，向左侧转头无力，右侧肩下垂且不能耸肩。出现该症状最可能的原因为","o":["左侧迷走神经损伤","右侧迷走神经损伤","左侧副神经损伤","右侧副神经损伤","右侧面神经损伤"],"a":3,"e":"副神经支配胸锁乳突肌和斜方肌，右侧损伤后向左侧转头无力、右肩下垂且不能耸肩，头转向对侧受限。"},{"q":"患者，女，68岁。轻微跌倒后患髋疼痛，不能站立、行走，髋后部肿胀、压痛、患肢外旋畸形。X线诊断为股骨颈骨折。骨折部位是","o":["股骨上端的半球形膨大处","股骨头下外侧的缩细部分","大、小转子之间的前面","大、小转子之间的后面","股骨内上髁上方的小突起"],"a":1,"e":"股骨颈为股骨头下外侧的狭细部分，与股骨体成颈干角，是老年人骨质疏松时最易发生骨折的部位。"},{"q":"患者，男，34岁。2个月前无明显诱因出现反复鼻出血，每次量不多，可自止，近3～4天，吸鼻有涕中带血。经鼻咽纤维喉镜检查发现鼻咽部有肿物，经内镜下肿物活检诊断为鼻咽癌。鼻咽癌容易发生于哪个部位","o":["咽鼓管圆枕","咽鼓管咽口","扁桃体上窝","咽隐窝","鼻咽部上壁"],"a":3,"e":"咽隐窝位于咽鼓管圆枕后方与咽后壁之间，是鼻咽癌最好发的部位，肿瘤易经破裂孔侵入颅内，早期即出现涕中带血及颈部淋巴结转移。"},{"q":"患者，女，56岁。自感乏力，有口渴感，消瘦。空腹血糖值14.5mmol/L，诊断为糖尿病。其发生可能由哪种激素分泌不足引起","o":["胰高血糖素","胰岛素","肾上腺素","糖皮质激素","褪黑素"],"a":1,"e":"胰岛素由胰岛β细胞分泌，是唯一降低血糖的激素；分泌不足致血糖升高、尿糖阳性，出现多饮多尿和消瘦。"},{"q":"患者，女，67岁。多饮、多食、消瘦10余年。门诊查空腹血糖12.5mmol/L，尿糖（++++）。半个月前突然出现视物模糊，其可能的病变部位在","o":["角膜","晶状体","玻璃体","房水","睫状体"],"a":1,"e":"长期高血糖使晶状体蛋白糖基化、渗透压改变，晶状体混浊形成糖尿病性白内障，导致视物模糊。"},{"q":"患者，男，50岁。乳突平面附近区域皮肤麻木感，进而感觉慢慢消失。可能受损伤的神经是","o":["第2胸神经","第4胸神经","第6胸神经","第8胸神经","第10胸神经"],"a":1,"e":"第4胸神经前支的皮支分布于乳头平面，该平面附近皮肤感觉减退以至消失，提示第4胸神经受损。"},{"q":"患者，男，75岁。下颌下淋巴结肿大，来自于下述哪个器官","o":["甲状腺","舌","喉","眼","外耳"],"a":1,"e":"舌的淋巴主要回流至下颌下淋巴结和颈深淋巴结，故舌部病变常首先引起下颌下淋巴结肿大。"},{"q":"患儿，女，3岁。咳嗽，嗓子疼，发热1周。今诉说耳朵疼。经检查发现鼓膜红、肿，外凸。初步诊断为中耳炎。中耳炎的主要感染途径是","o":["外耳道","外耳门","内耳道","咽鼓管","面神经管"],"a":3,"e":"咽鼓管为连通鼻咽与鼓室的长约3.5cm管道，鼻咽部感染易经此侵入鼓室，是化脓性中耳炎的主要感染途径。"},{"q":"一男性患者因昏迷入院治疗，以下哪项症状可以帮助医生作出患者“右侧内囊出血”的诊断","o":["右侧偏身感觉丧失","右侧躯干感觉丧失","左侧偏身感觉丧失","左侧躯干感觉丧失","右侧偏盲"],"a":2,"e":"内囊后肢含丘脑中央辐射，右侧内囊出血损伤该纤维，产生对侧即左侧偏身感觉丧失，常伴偏瘫和偏盲。"},{"q":"患者，女，18岁。拟诊白血病。需进行骨髓穿刺来检查骨髓象，穿刺抽取红骨髓。适合穿刺抽取的骨骼为","o":["股骨","髂骨","肱骨","椎骨","肩胛骨"],"a":1,"e":"成人椎骨、髂骨、肋骨、胸骨及长骨骨骺内终身存在红骨髓，临床常选髂前上棘或髂后上棘穿刺。"},{"q":"患者因丘脑肿瘤引起的丘脑综合征入院，经头颅CT显示肿瘤位于背侧丘脑腹后外侧核。患者可能出现的症状是","o":["变温症","同侧半躯干四肢浅感觉传导障碍","对侧半躯干四肢浅感觉传导障碍","同侧半躯干四肢深感觉传导障碍","对侧半躯干四肢深感觉传导障碍"],"a":4,"e":"腹后外侧核是躯干四肢深、浅感觉传导的共同中继站，接受内侧丘系和脊髓丘脑束纤维；该核受损出现对侧半身躯干四肢感觉障碍，其中深感觉即位置觉、振动觉障碍尤为突出。"},{"q":"患儿，男，17岁。因左眼眶骨折入院。经检查发现其左侧眼球向外下方活动受限。可能损伤了什么神经","o":["动眼神经","滑车神经","展神经","眼神经","鼻睫神经"],"a":1,"e":"上斜肌由滑车神经支配，收缩使瞳孔转向下外；该肌瘫痪后眼球不能向外下方转动，故左眶骨折出现外下活动受限。"},{"q":"患者，女。近视600度，昨日不慎头部受撞击后，右眼出现视野缺损，临床诊断为右眼视网膜脱落。其解剖学基础是","o":["视网膜双极细胞层与节细胞层之间存在潜在间隙","视网膜双极细胞层与感光细胞层之间存在潜在间隙","视网膜色素上皮层与神经层之间存在潜在间隙","视网膜与脉络膜之间存在潜在间隙","视网膜与玻璃体之间存在潜在间隙"],"a":2,"e":"视网膜视部与色素上皮层之间发育上存在潜在间隙，结合薄弱，受撞击后神经层与色素上皮层分离即形成视网膜脱离。"},{"q":"患者，56岁。出现椎动脉延髓支阻塞，出现对侧上、下肢瘫痪。该患者可能损伤了","o":["锥体束","皮质核束","丘脑腹后外侧核","红核","舌下神经核"],"a":0,"e":"锥体束在延髓锥体交叉以上下行，延髓支阻塞损伤一侧锥体束，引起对侧上、下肢痉挛性瘫痪。"},{"q":"患者，男，54岁。因胃溃疡穿孔，行胃大部切除术。术后3天，发热。胸部、腹部X线检查发现右膈抬高，活动度差，膈下未见游离气体。此患者可能并发","o":["右下肺炎","急性化脓性胆囊炎","右膈下脓肿","肝脓肿","十二指肠残端瘘"],"a":2,"e":"胃大部切除术后膈下间隙积血感染形成右膈下脓肿，表现为发热、右膈抬高且活动受限；膈下无游离气体可排除单纯穿孔。"},{"q":"患者，男，20岁，学生。主诉：右下颌骨膨隆1年余。现病史：1年前患者无意中发现右面部略隆起，因无症状未治疗，此后面部膨隆逐渐明显，因学习较忙而未就诊；2个月前感觉右下后牙有不适感；近1个月出现右下后牙疼痛，为阵发性，咀嚼时加重，偶有下唇麻木感。检查：面部不对称，右下颌区膨隆，范围约5cm×4cm×3cm，该区域皮肤未见异常；口内右下颌牙颊侧隆起，移行沟消失，表面黏膜无红肿。触诊有不适感，并有乒乓球感，无压痛。X线所见：相应于右下尖牙至下颌角区的下颌骨体部有圆形、多房状密度减低区，其边缘有密度增高的白色线条。范围已达下颌骨下缘。诊断：右下颌骨肉瘤。问：关于手术时需涉及的面动脉，叙述错误的是","o":["该动脉发自颈外动脉","该动脉主要供应下颌下腺、面部和腭扁桃体等","其体表投影为：在下颌骨下缘至咬肌后缘处作一连线，然后将连线连至内眦","其压迫止血部位为：在下颌骨下缘至咬肌前缘处，将面动脉压向下颌骨","压迫该动脉，其止血范围为面颊部"],"a":2,"e":"面动脉的体表投影为下颌骨下缘与咬肌前缘交点至内眦的连线，压迫止血应在此交点处将动脉压向下颌骨。"},{"q":"患者，男，45岁。骑电车不小心摔倒，右脚踝局部肿胀、疼痛。X线诊断为单纯外踝撕脱骨折。外踝位于","o":["胫骨下端内下的突起","胫骨下端外下的突起","腓骨下端的膨大","腓骨头下方缩窄的部分","腓骨上端的膨大"],"a":2,"e":"外踝为腓骨下端的膨大，构成距小腿关节的外侧壁，位置低于内踝；内踝则是胫骨下端内下方的突起，两者均可在体表扪及。"},{"q":"患者，男，26岁。不幸遭遇车祸导致骨盆骨折，医生检查后怀疑尿道受损。男性骨盆骨折时最常见的尿道损伤部位是","o":["尿道海绵体部","尿道球部","尿道前列腺部","尿道膜部","前尿道"],"a":3,"e":"尿道膜部穿过尿生殖膈，位置固定，骨盆骨折时易被撕裂，为男性尿道损伤最常见的部位。"},{"q":"患者，老年女性。因乳腺癌行乳腺癌根治术，清扫腋窝淋巴结。术后一侧肩胛骨内侧缘翘起，不能紧贴胸廓。应当考虑受损伤的神经是","o":["胸背神经","腋神经","肌皮神经","腓总神经","胸长神经"],"a":4,"e":"胸长神经支配前锯肌，乳癌根治术清扫腋窝淋巴结时易受损伤，前锯肌瘫痪后肩胛骨内侧缘翘起。"},{"q":"患者，女，53岁。因脑干肿瘤压迫动脉后出现右侧头面部痛温觉障碍，左侧上、下肢及躯干痛、温觉障碍等。请问该患者可能损伤了哪些结构","o":["左侧内侧丘系、左侧脊髓丘脑束","右侧三叉神经脊束、左侧脊髓丘脑束","右侧三叉神经脊束、右侧脊髓丘脑束","左侧内侧丘系、右侧脊髓丘脑束","左侧三叉神经脊束、右侧内侧丘系"],"a":2,"e":"右侧三叉神经脊束受损出现同侧即右侧头面部痛温觉障碍，右侧脊髓丘脑束受损出现对侧即左侧躯干四肢痛温觉障碍，二者并存提示右侧延髓外侧区病变。"},{"q":"患者患带状疱疹后先出现三叉神经痛，继而发现患者眼裂和口裂之间皮肤感觉障碍。可能是由三叉神经哪一支分支麻痹引起的","o":["眼神经","上颌神经","下颌神经","面神经","舌咽神经"],"a":1,"e":"上颌神经穿出眶下孔后分支分布于睑裂与口裂之间的皮肤，故该区感觉障碍提示上颌神经受损。"},{"q":"患者，男，26岁。在工地打工意外受伤。医生检查后发现受伤部位在右侧精索，该损伤不可能累及的结构是","o":["输精管","睾丸动脉","蔓状静脉丛","输精管血管","精囊"],"a":4,"e":"精索内由输精管、睾丸动脉、蔓状静脉丛及输精管血管等构成，精囊位于膀胱底后方，不属精索内容。"},{"q":"患者，男，23岁。面部口唇上方青春痘挤压后3天，头痛发热。血常规检查可见白细胞计数增高，怀疑有颅内感染。细菌进入颅内最可能经过的静脉","o":["面深静脉","颞浅静脉","上颌静脉","面静脉","颈内静脉"],"a":3,"e":"面静脉通过眼上、眼下静脉及面深静脉与海绵窦相通且无静脉瓣，故口唇周围感染易经面静脉入颅。"},{"q":"患者，男，58岁。因甲状腺肿瘤行甲状腺次全切除术，术后患者感觉头面部汗腺分泌障碍，上睑下垂。应当考虑下列哪一结构受损伤","o":["颈交感干","内脏大神经","内脏小神经","动眼神经","眼神经"],"a":0,"e":"颈交感干位于颈动脉鞘后方，损伤后交感神经功能障碍，出现Horner综合征，表现为上睑下垂、面部无汗。"},{"q":"患儿，女，12岁。因双眼视远物不清，伴眼部胀痛及头晕就诊。查左眼视力0.7，右眼视力0.9。应用阿托品后远视力可恢复正常，诊断为假性近视。该患者功能异常的结构是","o":["角膜","房水","晶状体","玻璃体","睫状肌"],"a":4,"e":"假性近视因睫状肌持续痉挛，晶状体屈度过强；阿托品麻痹睫状肌后调节放松、视力恢复，故异常结构为睫状肌。"},{"q":"患者，男，26岁。颌面外伤，张口受限。诊断为颧弓骨折。组成颧弓的骨是","o":["颞骨的乳突和颧骨的颞突","颞骨的颧突和颧骨的颞突","下颌骨的冠突和颧骨的颞突","上颌骨的颧突和颧骨的颞突","颞骨的乳突和颞骨的颧突"],"a":1,"e":"颧弓由颞骨的颧突与颧骨的颞突借缝连结构成，位于面部外侧皮下，骨折后可使张口受限。"},{"q":"患者，男，23岁。检查发现：患者颈5～胸1的脊髓白质前连合受损。患者会出现何种表现","o":["双上肢所有感觉缺失或减退","一侧上肢所有感觉缺失或减退","病变平面以下躯体痛、温觉减退，而深感觉和触觉保留","病变平面以下躯体所有感觉缺失或减退","双上肢痛温觉缺失或减退而深感觉和触觉保留"],"a":4,"e":"白质前连合内脊髓丘脑束的交叉纤维受损，阻断双侧痛温觉传导，而薄束、楔束位于后索不受累，故深感觉和触觉保留。"},{"q":"患者，男，50岁。长距离跑步，导致股四头肌功能受阻，表现为不能","o":["抬大腿","伸膝","仰卧起坐","内收大腿","外旋大腿"],"a":1,"e":"股四头肌是伸膝的唯一肌，由股神经支配；该肌功能障碍时不能主动伸膝，上下楼梯和起立困难。"},{"q":"患者，女，56岁。胃癌术后发现左锁骨上大窝有一肿大的淋巴结，试分析可能是下述哪组淋巴结","o":["右锁骨上淋巴结","左锁骨上淋巴结","颈浅淋巴结","左锁骨下淋巴结","右锁骨下淋巴结"],"a":1,"e":"胃癌细胞经胸导管注入左静脉角，再累及左锁骨上淋巴结，该处肿大提示腹腔脏器恶性肿瘤转移。"},{"q":"患者，男，20岁。因肛肠手术，需行椎管内麻醉。麻醉药物可经何处注入骶管","o":["骶粗隆","骶管裂孔","骶前孔","骶后孔","骶角"],"a":1,"e":"骶管下端开放为骶管裂孔，两侧可扪及骶角，是骶管麻醉的进针部位；骶前、后孔有骶神经前、后支通过。"},{"q":"患者，男，63岁。主诉：中上腹痛伴呕吐14小时。患者14小时前出现中上腹部疼痛，呈持续性钝痛，并逐渐加重，腰酸明显，疼痛在仰卧位加重，蜷曲位减轻，伴恶心、呕吐，呕吐2次胃内容物，解黄色稀便1次，在某卫生院肌内注射“消旋山莨菪碱”后疼痛无缓解，腹痛前参加聚餐饮白酒约200g及进食较多。既往曾有右上腹发作性疼痛史，3年前B超发现有“胆囊炎、胆囊结石”。体格检查：巩膜无黄染，皮肤黏膜未见瘀点、瘀斑心界无扩大，腹软，剑突下及剑脐间有压痛，无明显反跳痛及肌卫，Murphy征（-），肝脾肋下未及。腹部平片：肠腔少量积气以左上腹为主，气液平不明显，两膈下未见游离气体。B超：胆囊结石、胆囊炎；胰腺体积饱满回声稍低，肝、脾、双肾未见明显异常。上腹CT（平扫及增强）：胰腺体积增大，边缘毛糙，增强后密度尚均匀，余未见明显异常。急诊行腹腔探查。探查时下列动脉直接起于腹主动脉的有","o":["胃左动脉","肝总动脉","肠系膜上动脉","胃右动脉","脾动脉"],"a":2,"e":"肠系膜上、下动脉均直接起自腹主动脉，肠系膜上动脉在胰颈后方发出，供应空肠与回肠。"},{"q":"患者，女，53岁。近期自觉心悸气短入院检查。心电图、彩超检查均无异常，患者坚持要求进行冠脉造影检查。在检查过程中，可作为确定心缘标志的是","o":["前室间支","左缘支","后室间支","右缘支","右旋支"],"a":3,"e":"右缘支较粗大恒定，沿右心室下缘走行，冠状动脉造影时可用作确定心右缘的标志；左缘支同样恒定，可标志左心缘。"},{"q":"患者，女，47岁，一位女网球专业人士。告诉她的医生，她有肩袖损伤，需要手术。她的医生解释说，多年来肩关节周围的韧带损伤，逐渐加重了下方的肌肉损伤。下列哪一个韧带是医生最可能提到的","o":["肩锁韧带","喙肱韧带","肩胛横韧带","盂肱韧带","喙肩韧带"],"a":4,"e":"喙肩韧带与喙突、肩峰共同构成喙肩弓，架于肩关节上方；长期磨损增厚可压迫其下方的冈上肌腱，加重肩袖损伤。"},{"q":"一患者脑血管意外入院治疗，经检查右侧大脑中动脉中央支闭塞，患者会出现下列哪种症状","o":["右耳听力丧失","左耳听力丧失","左眼视野鼻侧和右眼视野颞侧偏盲","右眼视野鼻侧和左眼视野颞侧偏盲","双眼左侧视野同向性偏盲"],"a":4,"e":"大脑中动脉中央支供应内囊后肢，视辐射亦经此走行，右侧病变致左侧视野传导中断，出现双眼左侧视野同向性偏盲。"},{"q":"患者，女，50岁。车祸导致第10～12胸椎受损伤。可累及的脊髓节段是","o":["下胸段","全部腰段","全部骶段","全部腰骶段","全部骶尾段"],"a":1,"e":"成人脊髓下端平第1腰椎，腰髓节段约平对第10～12胸椎，故第10～12胸椎骨折可累及全部腰段；骶、尾髓节段则约平对第1腰椎。"},{"q":"患者，女，40岁。右侧乳房癌根治手术后，撑墙出现右侧“翼状肩”体征。损伤的肌是","o":["三角肌","前锯肌","斜方肌","肩胛下肌","背阔肌"],"a":1,"e":"胸长神经沿胸侧壁下行支配前锯肌，乳腺癌根治术清扫腋淋巴结时易损伤，致前锯肌瘫痪而出现翼状肩。"},{"q":"患者，女，64岁。5天前无明显诱因出现吞咽疼痛，呈持续性，刀割样，吞咽、说话时诱发疼痛，不能自行缓解。咽部喷洒局麻药（利多卡因）疼痛能轻微缓解。该患者诊断为“舌咽神经痛”。关于舌咽神经的描述，错误的是","o":["为混合性脑神经","与迷走神经和副神经同穿颈静脉孔","其咽支分布于咽壁，为一般内脏运动纤维","其舌支传导舌后1/3黏膜的一般感觉和味觉","其颈动脉窦支分布于颈动脉窦和颈动脉小球"],"a":2,"e":"舌咽神经咽支为3～4条细支，与迷走神经、交感神经咽支交织成咽丛，分布于咽壁各层，含一般内脏感觉纤维，接受咽部感觉传入而与咽反射相关，并非一般内脏运动纤维。"},{"q":"患者，男，27岁，著名钢琴家。因腕管综合征导致手指运动困难。瘫痪的肌包括","o":["骨间掌侧肌和拇收肌","骨间背侧肌和第1、2蚓状肌","第1、2蚓状肌和拇对掌肌","拇短展肌和骨间掌侧肌","第1、2、3、4蚓状肌"],"a":2,"e":"腕管内正中神经受压，其支配的拇短展肌、拇对掌肌及第1、2蚓状肌瘫痪，出现鱼际萎缩、拇指对掌不能。"},{"q":"患者，男，45岁。手术中损伤椎动脉后出现右侧软腭及咽喉肌麻痹，吞咽困难，声音嘶哑。请问该患者可能损伤了以下哪个结构","o":["左侧面神经核","左侧疑核","右侧疑核","右侧迷走神经背核","左侧迷走神经背核"],"a":2,"e":"疑核发出特殊内脏运动纤维经舌咽、迷走神经支配软腭及咽喉肌；右侧疑核受损出现同侧软腭和咽喉肌麻痹、吞咽困难及声音嘶哑。"},{"q":"患者，女，60岁。有风湿性心脏病史，长期服药治疗。近期出现全身无力、嘴唇发绀入院。心脏彩超检查发现患者二尖瓣关闭不全比较严重，拟进行瓣膜置换手术治疗。手术的入路部位是","o":["右心室前壁","右心室下壁","左心室前壁","左心室下壁","左心室侧壁"],"a":2,"e":"左心室前壁介于前室间沟、左房室沟与左缘支之间，血管分布较少，是二尖瓣等左心手术的入路部位。"},{"q":"患者，男，40岁。发现颈部有一包块，可随吞咽而上下移动。经医生诊断后行甲状腺次全切术，术后出现手足搐搦。与此症状相关的问题是","o":["甲状腺素分泌不足","甲状旁腺功能相对亢进","甲状腺侧叶切除时损伤甲状旁腺","甲状旁腺离甲状腺较远","分布于甲状腺的神经受损"],"a":2,"e":"甲状腺次全切除时损伤甲状旁腺或其血供，甲状旁腺素分泌不足使血钙降低，出现手足搐搦。"},{"q":"患者，男，24岁，是一位木工。遭受了整个小指的挤压伤。下列哪一种肌最有可能幸免","o":["指深屈肌","指伸肌","骨间掌侧肌","骨间背侧肌","蚓状肌"],"a":3,"e":"骨间背侧肌止于第2～4指指背腱膜，不作用于小指；小指运动由小鱼际肌、蚓状肌和骨间掌侧肌完成。"},{"q":"患者因头痛、恶心、呕吐入院，经诊断为脑水肿引起的颅内高压。该患者除了上述症状之外还有可能出现","o":["嗅觉障碍","听觉障碍","味觉障碍","面瘫","瞳孔对光反射减弱"],"a":4,"e":"颅内压增高使脑干受压、动眼神经受牵拉，其副交感纤维功能受损，瞳孔对光反射减弱，是脑疝的早期征象。"},{"q":"患者，男，76岁。突发脑出血后，出现右侧上、下肢及躯干意识性本体感觉和精细触觉障碍。经检查为椎动脉延髓支阻塞，请问该患者可能损伤了哪个结构","o":["左侧内侧丘系","左侧皮质核束","左侧锥体束","右侧内侧丘系","右侧皮质核束"],"a":0,"e":"内侧丘系在延髓内已经交叉，传导对侧躯干四肢的意识性本体感觉和精细触觉；椎动脉延髓支阻塞损伤左侧内侧丘系，即出现右侧上、下肢及躯干该感觉障碍。"},{"q":"患者，男，32岁。左腰部被刺，伤口持续出血，急诊入院。查体：脉搏120次/min，四肢冰冷，左上腹压痛，无腹肌紧张及反跳痛。考虑可能有腹腔器官损伤，最可能损伤的器官是","o":["肝","脾","胃","肾","横结肠"],"a":3,"e":"左腰部刺伤位置深在，肾为腹膜外位器官且紧贴后腹壁，故最易受损，出现血尿和肾区叩痛。"},{"q":"患者，女，53岁。因处于更年期心情烦躁，经常发脾气，此次和同事争吵后突发胸痛、气短入院。入院心脏彩超检查发现心包积液。关于心包错误的是","o":["分为纤维心包和浆膜心包","纤维心包伸缩性很小","浆膜心包又分为脏、壁两层","纤维心包与浆膜心包间为心包腔","心包腔内有少量浆液"],"a":3,"e":"心包腔是浆膜心包脏、壁两层之间的潜在腔隙，内含少量浆液；纤维心包与浆膜心包之间并无腔隙。"},{"q":"患者，男，43岁。检查发现其双侧对称分布的痛、温觉消失，本体感觉和精细触觉无障碍。可能损伤的部位是","o":["脊髓横断","脊髓半横断","脊髓白质前连合受损","脊髓前角损伤","脊髓后角损伤"],"a":2,"e":"白质前连合受损阻断脊髓丘脑束的交叉纤维，致双侧对称性痛、温觉消失；后索完好，故本体感觉和精细触觉保留，属分离性感觉障碍。"},{"q":"患者，女，67岁。无明显诱因感觉右侧肩部疼痛。根据牵涉性痛的特点，可以考虑下列哪一器官可能出现病变","o":["肝胆","心","胃","十二指肠","右肺"],"a":0,"e":"肝胆的感觉纤维经内脏大神经入T7～T10脊髓节段，与右肩部皮肤的感觉纤维进入同一节段，故肝胆病变常在右肩部出现牵涉痛。"},{"q":"患者，男，69岁。因突发腹部疼痛6小时入院。既往胃镜曾证实为胃溃疡。体质中等，无酗酒，脂肪餐史。伴有恶心，无呕吐，排大便1次，量少，有腹胀。查体：腹部平坦，腹肌紧张，全腹压痛，上腹部剑突下为重，伴反跳痛，肠鸣音弱。检验：白细胞明显升高，尿淀粉酶正常。腹部立位平片：2个小液平面，未见膈下游离气体。行开腹探查术，发现胃后壁穿孔。手术涉及到的行于胃小弯侧的动脉是","o":["胃左动脉、胃右动脉","胃左动脉、胃右动脉、肝总动脉","胃网膜左动脉、胃网膜右动脉","胃左动脉、肝总动脉、脾动脉","胃短动脉、胃后动脉"],"a":0,"e":"胃小弯侧由胃左动脉和胃右动脉供血，前者起自腹腔干，后者起自肝固有动脉，两动脉沿胃小弯吻合。"},{"q":"患者，女，35岁。主诉上腹部剧烈疼痛伴呕吐2天。患者于前日下午1时左右出现上腹部疼痛，剑突下为甚。疼痛剧烈难以忍受，呈持续性，放射至腰背部，伴有呕吐，呕吐物为胃内容物。检查：血糖依次为28.4mmol/L、26.9mmol/L、33.3mmol/L，血淀粉酶为865U/L。怀疑为急性重症胰腺炎（SAP）。急诊手术探查时需结扎的胰腺动脉来自","o":["胃左动脉","胃右动脉","胃短动脉","肝固有动脉","脾动脉"],"a":4,"e":"脾动脉沿胰上缘走行并发出胰支供应胰体和胰尾，故胰腺手术需处理的胰腺动脉主要来自脾动脉。"},{"q":"患者，男，37岁。在某星期六的早晨，与朋友踢足球时，足部损伤后被送往医院。一系列影像显示骨折累及距小腿关节（踝关节）。损伤主要影响的运动是","o":["足的背屈和跖屈","足的背屈、跖屈、内翻和外翻","足的内翻和外翻","足的背屈和外翻","足的跖屈和内翻"],"a":0,"e":"踝关节由胫、腓骨下端与距骨滑车构成，只能作背屈和跖屈；足的内翻、外翻由跗骨间关节完成，故踝部骨折主要影响背屈和跖屈。"},{"q":"患者，女，50岁。因进行性吞咽困难就诊。经食管镜检查并行活检，诊断为食管癌。食管癌常发生于食管的狭窄，关于食管狭窄的描述正确的是","o":["第1个狭窄距中切牙10cm","第1个狭窄对第7颈椎水平","第2个狭窄在左主支气管跨越食管左前方处","第2个狭窄距中切牙20cm","第3个狭窄在第11胸椎高度"],"a":2,"e":"第2狭窄为左主支气管跨越食管左前方处，相当于第4、5胸椎之间，距中切牙约25cm；第1狭窄在第6颈椎下缘、距中切牙15cm，第3狭窄平第10胸椎、距中切牙40cm。"},{"q":"患者，女，46岁。自感轻度呼吸困难，声音嘶哑。经医生检查，发现甲状腺上有包块。诊断为结节性甲状腺肿。该病在做甲状腺检查时可发现","o":["吞咽时可随喉向上下移动","吞咽时不随喉向上下移动","包块的移动与吞咽时喉的运动无关","吞咽时随喉向上下移动，是与甲状腺囊有关","吞咽时不随喉向上下移动，是与甲状腺鞘有关"],"a":0,"e":"甲状腺借甲状腺悬韧带连于喉软骨和气管软骨环，故吞咽时随喉上下移动，为触诊甲状腺的重要标志。"},{"q":"患者，女，40岁。诊断为右卵巢肿瘤而行腹腔镜手术，术中可见卵巢位于盆腔侧壁的什么位置","o":["髂总动脉起始处","髂总动脉末端前部","髂内动脉分叉处","髂内、外动脉起始处之间","髂外动脉与输尿管之间"],"a":3,"e":"卵巢位于盆腔侧壁髂内、外动脉起始部之间的卵巢窝内，借卵巢悬韧带和卵巢固有韧带固定。"},{"q":"患者，女，62岁。因肿瘤压迫中脑被盖后出现右侧除外直肌和上斜肌外的所有眼球外肌麻痹，瞳孔散大，左上、下肢及躯干意识性本体觉和精细触觉障碍。请问该患者可能损伤了哪些结构","o":["右动眼神经、右内侧丘系","右动眼神经、右脊髓丘脑束","左展神经、左内侧丘系","左动眼神经、左内侧丘系","右展神经、右内侧丘系"],"a":0,"e":"右侧动眼神经根受损致同侧除外直肌、上斜肌外的眼球外肌麻痹及瞳孔散大；右侧内侧丘系受损致对侧本体觉和精细触觉障碍。"},{"q":"患者，男，40岁。近日逐渐出现左侧上、下肢瘫痪，腱反射亢进，右侧眼球不能外视。可能的病变部位及其受损的结构是","o":["在左侧半中脑下丘高度腹内侧部，受损结构有锥体束和动眼神经根","在右侧半中脑下丘高度腹内侧部，受损结构有锥体束和动眼神经根","在左侧半脑桥上部高度腹内侧部，受损结构有锥体束和滑车神经根","在右侧半脑桥上部高度腹内侧部，受损结构有锥体束和滑车神经根","在右侧半脑桥下部高度腹内侧部，受损结构有锥体束和展神经根"],"a":4,"e":"脑桥下部腹侧病变损伤右侧锥体束和右侧展神经根，出现左侧上、下肢瘫痪及右眼球不能外视。"},{"q":"患者，女，67岁。突发脑出血后，出现左侧舌肌瘫痪。经检查为椎动脉延髓支阻塞。请问该患者可能损伤了哪个结构","o":["左侧舌下神经根","左侧舌咽神经根","左侧迷走神经","右侧舌下神经根","右侧舌咽神经根"],"a":0,"e":"舌下神经根由延髓前外侧沟出脑，行经延髓腹侧，椎动脉延髓支病变损伤左侧舌下神经根，致左舌肌瘫痪萎缩。"},{"q":"患儿，男，14岁。从滑板上摔下来，头撞在柏油路上。影像学检查显示蝶鞍破坏。损伤的骨是","o":["筛骨","枕骨","额骨","蝶骨","顶骨"],"a":3,"e":"蝶骨体上面中央凹陷为垂体窝，与鞍背共同构成蝶鞍，容纳垂体；影像显示蝶鞍破坏，说明骨折已累及蝶骨体。"},{"q":"一患者因脑血管意外入院治疗，经检查发现该患者左侧大脑中动脉闭塞。根据解剖学知识，该患者不会产生","o":["顶下小叶区域血供受到影响","听区血供受到影响","感觉性失语症","失读症","视觉出现障碍"],"a":4,"e":"视觉中枢位于枕叶，由大脑后动脉供血；大脑中动脉供应额、顶、颞叶外侧面，故其闭塞不引起视觉障碍。"},{"q":"患者，男，67岁。行腹股沟斜疝修补术后，感觉右侧腹股沟区阴囊部的皮肤感觉减退。最有可能损伤的神经是","o":["闭孔神经","髂腹股沟神经","髂腹下神经","生殖股神经","股神经"],"a":1,"e":"髂腹股沟神经经腹股沟管浅环穿出，分布于腹股沟区及阴囊（大阴唇）皮肤，疝修补术中易被损伤。"},{"q":"患者，男，35岁。头痛，恶心、呕吐，发热。查体：脑膜刺激征阳性。诊断为脑脊髓膜炎。在第3腰椎和第4腰椎棘突间行腰椎穿刺抽脑脊液化验。腰椎的棘突特征是","o":["短而分叉","长而不分叉","呈叠瓦状","呈板状，水平向后延伸","向下倾斜排列"],"a":3,"e":"腰椎棘突呈宽厚的板状，水平向后伸展，相邻棘突间隙宽大，是腰椎穿刺易于成功的解剖基础。"},{"q":"患儿，男，10岁。因垂体瘤出现双眼视野颞侧缺损。该肿瘤可压迫的结构是","o":["视交叉","上丘","视束","视辐射","视神经"],"a":0,"e":"垂体位于蝶鞍内，肿瘤向上生长压迫视交叉中央部来自视网膜鼻侧的交叉纤维，出现双眼颞侧视野缺损。"},{"q":"患者，男，63岁。因背部疼痛、虚弱和呼吸短促被送往急诊室。检查发现在膈肌主动脉裂孔处有腹主动脉瘤。下列结构最有可能被压缩的是","o":["迷走神经和奇静脉","食管及迷走神经","奇静脉和胸导管","胸导管与迷走神经","下腔静脉和膈神经"],"a":2,"e":"主动脉裂孔位于第12胸椎前方，有主动脉和胸导管通过，奇静脉亦经此上行入胸，瘤体扩大可压迫胸导管和奇静脉。"}];
